/* Eidos Design System — AI sub-DS component styles
 *
 * All .ai-* and .msg-* rules live here, NOT in ds.css. Moved out of ds.css
 * (~293 lines) plus page-local <style> blocks from the AI doc pages. Extends
 * the same tokens.css variables — no new tokens, no new design decisions.
 *
 * Import order (load-bearing cascade):
 *   tokens.css → ds.css → ai.css → ai-shell.css → example-shell → tailwind → globals
 *
 * Section map:
 *   1. Response (.ai-resp*)
 *   2. Prose (.ai-prose* / .ai-code* / .ai-diagram)
 *   3. Caret (.ai-caret / @keyframes ai-caret-blink / .msg-caret / @keyframes msg-blink)
 *   4. Citations (.ai-cite*)
 *   5. History (.ai-hist*)
 *   6. Message (.msg-thread / .msg / .msg-stack / .msg-bubble / .msg-actions / .msg-att*)
 *   7. Tool (.tool*)
 *   8. Reasoning (.rsn*)
 *   9. Suggestion (.sg / .sg-row / .sg-wrap / .sg-cards / .sg-card)
 *  10. Prompt input (.pi*)
 *  11. Conversation (.conv*)
 *  12. AI Label (.ai-label* / .ai-pop*)
 */

/* ─── 1. Response (.ai-resp*) ───────────────────────────────────────────────
   Long-form, bubble-less reply surface. Parallel system to .msg-* but built
   for editorial-scale model output: real heading hierarchy, tables, diagrams,
   code blocks, blockquotes. */

.ai-resp {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  max-width: 100%;
}
/* Avatar baseline — raise the avatar so its bottom edge aligns with the
   first line of prose text. The avatar (32 px) is taller than a single
   line of --ai-prose (15 px / 1.65 lh ≈ 25 px), so with plain flex-start
   it hangs ~7 px below the text baseline. A small negative margin-block-start
   lifts it until its bottom meets the cap-height / baseline of line 1. */
.ai-resp > .avatar {
  margin-block-start: -8px;
}
.ai-resp.user {
  flex-direction: row-reverse;
}
[dir="rtl"] .ai-resp.user { flex-direction: row; }

.ai-resp-stack {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
  flex: 1;
  max-width: 880px;
}
.ai-resp.user .ai-resp-stack {
  flex: 0 1 auto;
  max-width: 70%;
  align-items: flex-end;
}
[dir="rtl"] .ai-resp.user .ai-resp-stack { align-items: flex-start; }

.ai-resp-meta {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--font-mono); font-size: var(--text-xs);
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--fg-subtle);
}
.ai-resp-meta .name {
  color: var(--fg-muted);
  text-transform: none;
  letter-spacing: 0;
  font-size: 12px;
  font-family: var(--font-sans);
  font-weight: 500;
}
.ai-resp-meta .dot {
  width: 3px; height: 3px;
  border-radius: 50%;
  background: var(--fg-faint);
}

/* User question in document mode — compact bubble, no avatar. */
.ai-resp.user .ai-resp-q {
  padding: 10px 14px;
  background: var(--ember-soft);
  border: 1px solid rgba(255,107,53,0.22);
  border-radius: 12px;
  border-end-end-radius: 4px;
  color: var(--fg);
  font-size: var(--text-md);
  line-height: 1.55;
  word-wrap: break-word;
}
[dir="rtl"] .ai-resp.user .ai-resp-q {
  border-end-end-radius: 12px;
  border-end-start-radius: 4px;
}

.ai-resp-actions {
  display: inline-flex; gap: 2px;
  margin-top: 6px;
  opacity: 0.55;
  transition: opacity var(--dur-fast) var(--ease);
}
.ai-resp:hover .ai-resp-actions,
.ai-resp-actions:focus-within { opacity: 1; }
.ai-resp-action {
  width: 28px; height: 28px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 6px;
  color: var(--fg-subtle);
  cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.ai-resp-action:hover { background: var(--surface-hover); color: var(--fg); }
.ai-resp-action.is-on.thumb-up { color: var(--success); }
.ai-resp-action.is-on.thumb-down { color: var(--danger); }

/* ─── 2. Prose (.ai-prose* / .ai-code* / .ai-diagram) ──────────────────────
   Editorial typography for streamdown bodies. */

.ai-prose {
  color: var(--fg);
  font-size: 15px;
  line-height: 1.65;
  text-wrap: pretty;
}
.ai-prose > * { max-width: 68ch; }
.ai-prose > .ai-wide,
.ai-prose > figure,
.ai-prose > table,
.ai-prose > .ai-code,
.ai-prose > .ai-diagram { max-width: 100%; }

.ai-prose h1,
.ai-prose h2,
.ai-prose h3 {
  color: var(--fg);
  font-weight: 600;
  line-height: 1.25;
  letter-spacing: -0.01em;
}
.ai-prose h1 { font-size: 28px; margin: 1.6em 0 0.5em; letter-spacing: -0.02em; }
.ai-prose h2 { font-size: 22px; margin: 1.6em 0 0.4em; }
.ai-prose h3 { font-size: 17px; margin: 1.4em 0 0.4em; }
.ai-prose > :first-child { margin-top: 0; }
.ai-prose > h1:first-child,
.ai-prose > h2:first-child,
.ai-prose > h3:first-child { margin-top: 0; }

.ai-prose p { margin: 0 0 0.9em; }
.ai-prose p:last-child { margin-bottom: 0; }
.ai-prose strong { font-weight: 600; color: var(--fg); }
.ai-prose em { font-style: italic; }
.ai-prose a {
  color: var(--ember);
  text-decoration: underline;
  text-underline-offset: 2px;
}
.ai-prose a:hover { color: var(--ember-glow); }

/* Lists — bullet and numbered markers share the same custom positioning so
   they begin at the SAME x and use the SAME marker → text gap. Native
   list-style places the bullet differently from the OL number (which is
   why ordered lists used a custom counter from the start); using the same
   ::before strategy for both keeps the two list types visually consistent
   in mixed-list responses. */
.ai-prose ul,
.ai-prose ol {
  list-style: none;
  margin: 0 0 0.9em;
  padding-inline-start: 32px;
}
.ai-prose li {
  position: relative;
  margin-bottom: 6px;
}
.ai-prose li > ul,
.ai-prose li > ol { margin: 6px 0 0; }

/* Bullet marker — • aligned to the same trailing edge as OL numbers
   (12px LEFT of the text). Slightly larger glyph so the bullet reads at
   the same optical weight as the digits. */
.ai-prose ul > li::before {
  content: "•";
  position: absolute;
  inset-inline-end: calc(100% + 12px);
  top: 0;
  color: var(--fg-subtle);
  font-size: 1.15em;
  line-height: inherit;
  min-inline-size: 1.4em;
  text-align: end;
}

/* Numbered marker — counter-based so it stays consistent with nested
   lists and tabular-numerals keep two-digit numbers aligned with
   single-digit ones. */
.ai-prose ol { counter-reset: ai-prose-ol; }
.ai-prose ol > li { counter-increment: ai-prose-ol; }
.ai-prose ol > li::before {
  content: counter(ai-prose-ol) ".";
  position: absolute;
  inset-inline-end: calc(100% + 12px);
  top: 0;
  color: var(--fg-subtle);
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  min-inline-size: 1.4em;
  text-align: end;
}
/* Nested ol — restart the counter so 1./2./3. resets inside each parent. */
.ai-prose ol ol { counter-reset: ai-prose-ol; }

/* Inline code */
.ai-prose :not(pre) > code {
  font-family: var(--font-mono);
  font-size: 0.86em;
  padding: 1px 6px;
  border-radius: 4px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  color: var(--ember);
}

/* Block code — header (lang + copy) + scrollable body */
.ai-prose .ai-code {
  margin: 18px 0;
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  background: var(--bg-elevated);
  overflow: hidden;
}
.ai-prose .ai-code-head {
  display: flex; align-items: center; gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border);
  background: var(--surface);
  font-family: var(--font-mono); font-size: var(--text-xs);
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--fg-subtle);
}
.ai-prose .ai-code-head .lang { color: var(--fg-muted); }
.ai-prose .ai-code-head .spacer { flex: 1; }
.ai-prose .ai-code-copy {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 3px 7px;
  background: transparent;
  border: 1px solid var(--border-strong);
  border-radius: 4px;
  color: var(--fg-muted);
  font: 500 10.5px var(--font-mono);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.ai-prose .ai-code-copy:hover {
  color: var(--fg);
  border-color: var(--border-stronger);
  background: var(--surface);
}
.ai-prose .ai-code-body {
  margin: 0;
  padding: 12px 14px;
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  line-height: 1.6;
  color: var(--fg);
  overflow-x: auto;
}

/* Token classes for hand-tokenized code samples inside .ai-code-body.
   The DS doesn't bundle Shiki/Prism — these are just colour roles that
   render any consumer-supplied <span class="tok-…">…</span> tokens with
   the Eidos palette. Use them sparingly in docs/demos; in production a
   build-time highlighter (Shiki, react-syntax-highlighter) is recommended. */
.ai-code-body .tok-key { color: var(--ember); }
.ai-code-body .tok-str { color: var(--success, #34D399); }
.ai-code-body .tok-num { color: var(--info, #60A5FA); }
.ai-code-body .tok-com { color: var(--fg-faint); font-style: italic; }
.ai-code-body .tok-fn  { color: var(--info, #60A5FA); }
.ai-code-body .tok-typ { color: #C792EA; }
.ai-code-body .tok-op  { color: var(--fg-muted); }
.ai-code-body .tok-var { color: var(--fg); }

/* Blockquote */
.ai-prose blockquote {
  margin: 16px 0;
  padding: 4px 0 4px 16px;
  border-inline-start: 2px solid var(--ember);
  color: var(--fg-muted);
  font-style: italic;
  font-size: var(--text-body);
  line-height: 1.6;
}
.ai-prose blockquote p { margin: 0; }
.ai-prose blockquote cite {
  display: block;
  margin-top: 8px;
  font-family: var(--font-mono);
  font-size: 11px;
  font-style: normal;
  letter-spacing: 0.04em;
  color: var(--fg-subtle);
}

/* Tables — editorial density, mono header */
.ai-prose table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  margin: 18px 0;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}
.ai-prose thead th {
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--fg-subtle);
  font-weight: 500;
  text-align: start;
  padding: 10px 14px;
  background: var(--bg-elevated);
  border-bottom: 1px solid var(--border-strong);
}
.ai-prose tbody td {
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  color: var(--fg);
  vertical-align: top;
  line-height: 1.5;
}
.ai-prose tbody tr:last-child td { border-bottom: none; }
.ai-prose td.num,
.ai-prose th.num { text-align: end; font-variant-numeric: tabular-nums; }

/* Figure — image / svg / diagram with mono caption */
.ai-prose figure {
  margin: 18px 0;
  padding: 0;
}
.ai-prose figure > img,
.ai-prose figure > svg {
  display: block;
  width: 100%;
  height: auto;
  border-radius: 8px;
  border: 1px solid var(--border);
}
.ai-prose figure figcaption {
  margin-top: 10px;
  font-family: var(--font-mono);
  font-size: 11px;
  letter-spacing: 0.04em;
  color: var(--fg-subtle);
  line-height: 1.5;
}

/* Diagram slot — bordered surface for SVG / Mermaid / custom drawings */
.ai-prose .ai-diagram {
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  padding: 28px 24px;
  overflow: auto;
}
.ai-prose .ai-diagram svg { display: block; margin: 0 auto; max-width: 100%; }

/* Horizontal rule — quiet break between major sections */
.ai-prose hr {
  margin: 28px 0;
  border: none;
  border-top: 1px solid var(--border);
}

/* ─── 3. Caret (.ai-caret / .msg-caret) ────────────────────────────────────
   Drop-in streaming cursors used by Message and Response surfaces.
   Shape: fixed 6×14 block, ember fill, 1s blink. */

.ai-caret {
  display: inline-block;
  width: 6px;
  height: 14px;
  vertical-align: -2px;
  margin-inline-start: 2px;
  background: var(--ember);
  border-radius: 1px;
  animation: ai-caret-blink 1s steps(1) infinite;
}
@keyframes ai-caret-blink { 50% { opacity: 0; } }
@media (prefers-reduced-motion: reduce) {
  .ai-caret, .msg-caret { animation: none; opacity: 1; }
}

/* Streaming caret — assistant only (msg variant) */
.msg-caret {
  display: inline-block; width: 6px; height: 14px;
  vertical-align: -2px; margin-inline-start: 2px;
  background: var(--ember); border-radius: 1px;
  animation: msg-blink 1s steps(1) infinite;
}
@keyframes msg-blink { 50% { opacity: 0; } }

/* ─── 4. Citations (.ai-cite*) ──────────────────────────────────────────────*/

.ai-cite-wrap { position: relative; display: inline-block; }
.ai-cite-chip {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 16px; height: 16px; padding: 0 4px;
  font: 600 10.5px/1 var(--font-mono);
  font-feature-settings: 'tnum';
  color: var(--ember);
  background: var(--ember-soft);
  border: 1px solid rgba(255,107,53,0.28);
  border-radius: 4px;
  cursor: pointer;
  vertical-align: 2px;
  margin-inline-start: 2px;
  transition: all var(--dur-fast) var(--ease);
}
.ai-cite-chip:hover { background: var(--ember); color: var(--ember-fg); border-color: var(--ember); }
.ai-cite-chip:focus-visible { outline: 2px solid var(--ember); outline-offset: 1px; }
.ai-cite-pop {
  position: absolute; z-index: 40;
  bottom: calc(100% + 8px); inset-inline-start: 0;
  width: 280px;
  display: flex; flex-direction: column; gap: 4px;
  padding: 10px 12px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  box-shadow: var(--elev-3);
  font: 400 12px/1.45 var(--font-sans);
}
.ai-cite-pop-head { display: flex; align-items: center; justify-content: space-between; }
.ai-cite-pop-dom { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-subtle); letter-spacing: 0.04em; text-transform: uppercase; }
.ai-cite-pop-rank { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--ember); }
.ai-cite-pop-title { color: var(--fg); font-weight: 500; font-size: var(--text-sm); line-height: 1.35; }
.ai-cite-pop-snip { color: var(--fg-muted); font-size: var(--text-xs); line-height: 1.5; }
.ai-cite-pop-foot { display: inline-flex; align-items: center; gap: 4px; margin-top: 4px; padding-top: 6px; border-top: 1px solid var(--border); color: var(--fg-faint); font-family: var(--font-mono); font-size: var(--text-xs); }
.ai-cite-pop-foot .url { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
/* Sources panel — flat: no outer card, no per-row borders (hairlines only),
   no chip on rank (just mono number). Typography carries the structure.
   Header matches ChainOfThought: chevron + mono uppercase label + count. */
.ai-cite-panel { background: none; border: 0; border-radius: 0; padding: 0; overflow: visible; }
.ai-cite-panel-head {
  display: inline-flex; align-items: center; gap: 7px;
  background: none; border: 0; padding: 0; cursor: pointer; text-align: start;
  margin-bottom: 14px;
  font-family: var(--font-mono); font-size: var(--text-xs);
  letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--fg-muted);
}
button.ai-cite-panel-head { cursor: pointer; }
.ai-cite-panel-head:hover { color: var(--fg); }
.ai-cite-panel-head .chev { color: var(--fg-faint); transition: transform 0.18s ease; flex: 0 0 auto; margin-inline-start: 2px; }
.ai-cite-panel[data-open="true"] .ai-cite-panel-head .chev { transform: rotate(180deg); }
.ai-cite-panel-head .label { color: var(--ember); font-weight: 500; }
.ai-cite-panel-head .count {
  display: inline; background: none; padding: 0; min-width: 0; height: auto;
  color: var(--fg-faint); font-size: var(--text-xs); font-family: var(--font-mono);
  border-radius: 0;
}
.ai-cite-panel-head .count::before { content: '· '; color: var(--fg-faint); }

/* Pager — left/right arrows + position indicator, shown when > perPage */
.ai-cite-panel-pager {
  display: flex; align-items: center; justify-content: flex-end; gap: 10px;
  margin-top: 14px; padding-top: 14px; border-top: 1px solid var(--border);
}
.ai-cite-panel-pager-pos {
  font-family: var(--font-mono); font-size: var(--text-xs);
  color: var(--fg-muted); letter-spacing: 0.04em;
}
.ai-cite-panel-pager-pos .of { color: var(--fg-faint); }
.ai-cite-panel-pager-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border-radius: 6px;
  background: none; border: 1px solid var(--border); cursor: pointer;
  color: var(--fg-muted); transition: color 0.14s ease, border-color 0.14s ease;
}
.ai-cite-panel-pager-btn:hover:not(:disabled) { color: var(--ember); border-color: rgba(255,107,53,0.4); }
.ai-cite-panel-pager-btn:disabled { color: var(--fg-faint); border-color: var(--border); cursor: not-allowed; opacity: 0.5; }
.ai-cite-panel-list { list-style: none; padding: 0; margin: 0; }
.ai-cite-panel-list li {
  display: grid;
  grid-template-columns: 28px 1fr;
  column-gap: 12px; row-gap: 4px;
  padding: 14px 0;
  border-bottom: 1px solid var(--border);
}
.ai-cite-panel-list li:first-child { padding-top: 0; }
.ai-cite-panel-list li:last-child { border-bottom: none; padding-bottom: 0; }
.ai-cite-panel-list .rank {
  grid-row: 1 / 4;
  display: block; width: auto; height: auto; padding: 2px 0 0;
  background: none; color: var(--fg-faint);
  font: 500 var(--text-xs)/1.4 var(--font-mono);
  border-radius: 0; text-align: start;
}
.ai-cite-panel-list .title {
  display: flex; align-items: baseline; justify-content: space-between; gap: 12px;
  color: var(--fg); font-size: var(--text-sm); font-weight: 500;
  text-decoration: none; line-height: 1.4;
}
.ai-cite-panel-list .title:hover { color: var(--ember); }
.ai-cite-panel-list .title .url {
  display: inline-flex; align-items: center; gap: 4px;
  font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint);
  font-weight: 400; white-space: nowrap;
}
.ai-cite-panel-list .snip { color: var(--fg-muted); font-size: var(--text-base); line-height: 1.55; }
.ai-cite-panel-list .meta {
  display: inline-flex; align-items: center; gap: 4px;
  font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint);
}
[dir="rtl"] .ai-cite-pop { inset-inline-start: auto; inset-inline-end: 0; }

/* ─── 5. History (.ai-hist*) ────────────────────────────────────────────────*/

.ai-hist {
  display: flex; flex-direction: column;
  width: 280px; height: 100%;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}
.ai-hist.fluid { width: 100%; }
.ai-hist-head {
  display: flex; align-items: center; gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--border);
}
.ai-hist-new {
  flex: 1;
  display: inline-flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 10px;
  background: var(--ember); color: var(--ember-fg);
  border: 1px solid var(--ember); border-radius: 8px;
  font: 600 12.5px/1 var(--font-sans); cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.ai-hist-new:hover { background: var(--ember-glow); border-color: var(--ember-glow); }
.ai-hist-new:focus-visible { outline: var(--ring-width) solid var(--ring); outline-offset: var(--ring-offset); }
.ai-hist-icon-btn {
  width: 32px; height: 32px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: 1px solid var(--border-strong);
  border-radius: 8px; color: var(--fg-muted); cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.ai-hist-icon-btn:hover { background: var(--surface-hover); color: var(--fg); }
.ai-hist-search {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 10px; margin: 8px 8px 4px;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: 7px;
  color: var(--fg-faint);
}
.ai-hist-search.is-active { border-color: var(--ember); box-shadow: 0 0 0 2px var(--ember-soft); }
.ai-hist-search input {
  flex: 1; min-width: 0;
  background: transparent; border: none; outline: none;
  color: var(--fg); font: 400 12.5px/1 var(--font-sans);
  padding: 4px 0;
}
.ai-hist-search input::placeholder { color: var(--fg-faint); }
.ai-hist-search input:focus-visible { outline: var(--ring-width) solid var(--ring); outline-offset: var(--ring-offset); border-radius: 4px; }
.ai-hist-list {
  flex: 1; min-height: 0;
  overflow-y: auto;
  padding: 4px 6px 8px;
}
.ai-hist-group {
  margin-top: 10px;
}
.ai-hist-group:first-child { margin-top: 4px; }
.ai-hist-group-head {
  display: flex; align-items: center; justify-content: space-between;
  padding: 6px 8px 4px;
  font-family: var(--font-mono); font-size: 10px;
  letter-spacing: 0.08em; text-transform: uppercase;
  color: var(--fg-faint);
}
.ai-hist-item {
  display: flex; align-items: flex-start; gap: 6px;
  padding: 8px 8px 8px 8px;
  border-radius: 6px; cursor: pointer;
  position: relative;
  color: var(--fg-muted);
  transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);
}
.ai-hist-item:hover { background: var(--surface-hover); color: var(--fg); }
.ai-hist-item:focus-visible { outline: var(--ring-width) solid var(--ring); outline-offset: -1px; }
.ai-hist-item.is-active {
  background: var(--ember-soft);
  color: var(--ember);
}
.ai-hist-item .body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }
.ai-hist-item .title {
  font-size: var(--text-sm); font-weight: 500; color: var(--fg);
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.ai-hist-item.is-active .title { color: var(--ember); }
.ai-hist-item .preview {
  font-size: var(--text-xs); line-height: 1.4; color: var(--fg-subtle);
  display: -webkit-box; -webkit-line-clamp: 1; -webkit-box-orient: vertical;
  overflow: hidden;
}
.ai-hist-item .star {
  flex: 0 0 auto;
  width: 14px; height: 14px;
  color: var(--warning);
  margin-top: 2px;
}
.ai-hist-item .actions {
  position: absolute; inset-inline-end: 6px; top: 6px;
  display: none; gap: 2px;
  background: var(--bg-elevated);
  border-radius: 5px;
  padding: 2px;
}
.ai-hist-item:hover .actions,
.ai-hist-item:focus-within .actions { display: inline-flex; }
.ai-hist-item .act {
  width: 22px; height: 22px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: none; border-radius: 4px;
  color: var(--fg-subtle); cursor: pointer;
}
.ai-hist-item .act:hover { background: var(--surface-hover); color: var(--fg); }
.ai-hist-item .act:focus-visible { outline: var(--ring-width) solid var(--ring); outline-offset: 1px; }
.ai-hist-item .act.danger:hover { color: var(--danger); }
.ai-hist-item .hl { color: var(--ember); background: rgba(255,107,53,0.12); border-radius: 2px; padding: 0 1px; }

.ai-hist-empty {
  padding: 32px 16px;
  text-align: center;
  color: var(--fg-faint);
}
.ai-hist-empty .ico {
  display: inline-flex; align-items: center; justify-content: center;
  width: 36px; height: 36px;
  background: var(--surface); color: var(--fg-subtle);
  border-radius: 50%;
  margin-bottom: 10px;
}
.ai-hist-empty .title { color: var(--fg-muted); font-size: 13px; font-weight: 500; }
.ai-hist-empty .sub { color: var(--fg-faint); font-size: 12px; margin-top: 4px; }

.ai-hist-rename {
  display: flex; gap: 4px; padding: 4px 6px;
  border-radius: 6px;
  background: var(--surface);
  border: 1px solid var(--ember);
  box-shadow: 0 0 0 2px var(--ember-soft);
}
.ai-hist-rename input {
  flex: 1; min-width: 0;
  background: transparent; border: none; outline: none;
  color: var(--fg); font: 500 var(--text-sm)/1.5 var(--font-sans);
}

/* Reduced motion — collapse the row tint transition and the new/icon button
   `transition: all` so the hover-action reveal and panel land instantly. */
@media (prefers-reduced-motion: reduce) {
  .ai-hist-item, .ai-hist-new, .ai-hist-icon-btn { transition: none; }
}

/* ─── 6. Message (.msg-thread / .msg / .msg-*) ──────────────────────────────
 *
 * Canonical bubble styles for one turn of a conversation. Used by:
 *   • <Message/> primitive exported from atoms.tsx (@/ds/core)
 *   • the ai/message documentation page
 *   • the ai/conversation thread (via variant="compact")
 *   • any future surface that needs an inline chat turn
 *
 * Class contract:
 *   .msg-thread       container — flex column with 18px gap
 *   .msg              one turn — flex row, role drives alignment
 *   .msg-stack        bubble + meta + actions vertical stack
 *   .msg-bubble       the bubble itself (border + bg)
 *   .msg-meta         caption row above the bubble
 *   .msg-actions      hover-revealed action toolbar
 *   .msg-action       single action button
 *   .msg-att-row      file/image attachment chips
 *   .msg-caret        streaming caret (blinks)  ← declared in section 3
 *   .msg.is-error     error-state styling
 *   .msg.compact      smaller bubble (sidebars / dense threads)
 *   .msg.plain        bubble-less variant (in document-mode threads)
 */

/* ── AI chat spacing scale ──────────────────────────────────────────────
   Custom-property tokens so both .msg-thread (canonical) and .conv-body
   (full conversation shell) share one source of truth. Hosts can override
   any token to tighten/loosen for a specific surface (a compact insight
   reply might shrink --ai-thread-pad-inline; a docked artifact host might
   bump it for breathing room from the drawer edge).
   ───────────────────────────────────────────────────────────────────── */
.msg-thread, .conv-body {
  --ai-thread-pad-block: 24px;   /* top/bottom of the scroll body */
  --ai-thread-pad-inline: 24px;  /* L/R — keeps avatars off container edges */
  --ai-turn-gap: 24px;           /* gap between DIFFERENT speakers */
  --ai-turn-gap-follow: 6px;     /* gap between SAME-speaker follow-ups */
  --ai-avatar-gap: 12px;         /* between avatar and bubble */
}

.msg-thread {
  display: flex; flex-direction: column;
  padding: var(--ai-thread-pad-block) var(--ai-thread-pad-inline);
  max-width: 720px;
}
.msg-thread.fluid { max-width: none; }

/* Turn-change is the default gap; same-speaker follow-ups collapse closer. */
.msg-thread > .msg + .msg,
.conv-body  > .msg + .msg { margin-block-start: var(--ai-turn-gap); }
.msg-thread > .msg.user + .msg.user,
.msg-thread > .msg.assistant + .msg.assistant,
.msg-thread > .msg.system + .msg.system,
.conv-body  > .msg.user + .msg.user,
.conv-body  > .msg.assistant + .msg.assistant,
.conv-body  > .msg.system + .msg.system { margin-block-start: var(--ai-turn-gap-follow); }

.msg {
  display: flex; align-items: flex-end; gap: var(--ai-avatar-gap, 12px);
  max-width: 100%;
}

/* ── Burst pattern ─────────────────────────────────────────────────────
   When the same speaker sends consecutive messages:
   • The avatar only appears next to the LAST message of the burst (other
     messages keep the space via visibility:hidden so the bubble stays
     horizontally aligned with the rest of the thread).
   • The meta row (name + time + model) only appears above the FIRST
     message of the burst (subsequent same-speaker turns hide it).
   • align-items: flex-end (above) anchors the avatar to the bottom of
     the last bubble.
   ─────────────────────────────────────────────────────────────────── */
.msg.user:has(+ .msg.user) .avatar,
.msg.assistant:has(+ .msg.assistant) .avatar,
.msg.system:has(+ .msg.system) .avatar { visibility: hidden; }
.msg-thread > .msg.user + .msg.user .msg-meta,
.msg-thread > .msg.assistant + .msg.assistant .msg-meta,
.msg-thread > .msg.system + .msg.system .msg-meta,
.conv-body  > .msg.user + .msg.user .msg-meta,
.conv-body  > .msg.assistant + .msg.assistant .msg-meta,
.conv-body  > .msg.system + .msg.system .msg-meta { display: none; }
.msg.user { flex-direction: row-reverse; }
.msg.user .msg-stack { align-items: flex-end; }
[dir="rtl"] .msg.user { flex-direction: row; }
[dir="rtl"] .msg.user .msg-stack { align-items: flex-start; }
[dir="rtl"] .msg.assistant .msg-stack { align-items: flex-end; }

.msg-stack {
  display: flex; flex-direction: column; gap: 6px;
  min-width: 0; max-width: 78%;
}
/* Assistant replies have no bubble — let them use more of the column so
   long-form content (tables, code, equations, lists) doesn't get squeezed.
   User messages stay capped at 78% so they keep reading as a quoted prompt
   above the answer, not a paragraph competing with it. */
.msg.assistant .msg-stack { max-width: 92%; }

.msg-meta {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--font-mono); font-size: var(--text-xs);
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--fg-subtle);
}
.msg-meta .name { color: var(--fg-muted); text-transform: none; letter-spacing: 0; font-size: 12px; font-family: var(--font-sans); font-weight: 500; }
.msg-meta .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--fg-faint); }

.msg-bubble {
  padding: 12px 14px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--surface);
  color: var(--fg);
  font-size: var(--text-sm); line-height: 1.6;
  word-wrap: break-word;
  max-width: 100%;
}
.msg.user .msg-bubble {
  background: var(--ember-soft);
  border-color: rgba(255,107,53,0.22);
  color: var(--fg);
}
/* Assistant replies read as FLAT prose — no bubble surface. Only the user
   side keeps its ember-soft bubble (its role is to read as a quoted prompt
   above the answer). This matches the modern chat pattern (Claude, ChatGPT)
   where the AI reply is the page-level content and the user message is the
   small chip pinned above it. */
.msg.assistant .msg-bubble {
  background: transparent;
  border: 0;
  padding: 0;
  border-radius: 0;
}
/* The pre/code/blockquote inside an assistant reply still need their own
   surface — restore the bg-elevated chrome on code, since the bubble used
   to provide contrast against them. */
.msg.assistant .msg-bubble pre {
  background: var(--bg-elevated);
}
/* Inline code inside assistant prose: keep the ember tint but drop the
   border that used to read against the bubble (no bubble = redundant). */
.msg.assistant .msg-bubble code:not(pre code) {
  border: 0;
}

/* Avatar alignment — when the message has actions / attachments / errors
   stacked under the bubble, the flex-end alignment otherwise drops the
   avatar to the BOTTOM of those rows. Lift the avatar by the action row's
   height so it aligns with the BUBBLE's bottom edge. */
.msg:has(.msg-actions) > .avatar { margin-block-end: 32px; }
.msg:has(.msg-att-row) > .avatar { margin-block-end: 12px; }
.msg:has(.msg-error-row) > .avatar { margin-block-end: 24px; }

/* All bubble corners are equal 12px — no asymmetric "tail" corner. The
   tail was a barely-visible 4px cut on one corner; removing it gives a
   cleaner, more confident bubble that reads symmetrically. */

.msg.system .msg-bubble {
  background: transparent;
  border: 1px dashed var(--border-strong);
  color: var(--fg-muted);
  font-family: var(--font-mono);
  font-size: 12px;
  text-align: center;
}
.msg.system .msg-stack { max-width: 100%; align-items: stretch; }

.msg-bubble p { margin: 0 0 8px; }
.msg-bubble p:last-child { margin-bottom: 0; }
.msg-bubble ul { margin: 6px 0 0; padding-inline-start: 18px; }
.msg-bubble ul li { margin-bottom: 2px; }
.msg-bubble code:not(pre code) {
  font-family: var(--font-mono); font-size: 12px;
  padding: 1px 5px; border-radius: 4px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  color: var(--ember);
}
.msg-bubble pre {
  margin: 8px 0 0;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
  font-family: var(--font-mono); font-size: 12px;
  color: var(--fg-muted);
  overflow-x: auto;
  line-height: 1.55;
}
.msg-bubble a { color: var(--ember); text-decoration: underline; text-underline-offset: 2px; }
.msg-bubble a:hover { color: var(--ember-glow); }

.msg-actions {
  display: inline-flex; gap: 2px; margin-top: 4px;
  opacity: 0.6; transition: opacity var(--dur-fast) var(--ease);
}
.msg:hover .msg-actions, .msg-actions:focus-within { opacity: 1; }
.msg-action {
  width: 26px; height: 26px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: 1px solid transparent; border-radius: 6px;
  color: var(--fg-subtle); cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.msg-action:hover { background: var(--surface-hover); color: var(--fg); }
.msg-action.is-on.thumb-up { color: var(--success); }
.msg-action.is-on.thumb-down { color: var(--danger); }

/* Attachments displayed inside a message */
.msg-att-row { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 8px; }
.msg-att {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 6px 10px 6px 8px;
  border: 1px solid var(--border-strong);
  border-radius: 6px;
  background: var(--bg);
  font-size: 12px;
  color: var(--fg-muted);
  max-width: 220px;
}
.msg-att .ico {
  width: 22px; height: 22px; display: inline-flex; align-items: center; justify-content: center;
  background: var(--surface); border-radius: 4px;
  color: var(--fg-subtle);
}
.msg-att .name { color: var(--fg); font-weight: 500; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.msg-att .sz { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint); }

/* Error state */
.msg.is-error .msg-bubble {
  border-color: rgba(248,113,113,0.35);
  background: var(--danger-soft);
  color: var(--fg);
}
.msg-error-row {
  display: inline-flex; align-items: center; gap: 6px;
  margin-top: 8px; font-size: 12px; color: var(--danger);
}

/* variant="compact" — smaller bubble for sidebars / dense threads */
.msg.compact .msg-stack { gap: 4px; max-width: 84%; }
.msg.compact .msg-bubble {
  padding: 8px 11px;
  border-radius: 10px;
  font-size: var(--text-sm);
  line-height: 1.55;
}
.msg.compact .msg-bubble pre { margin: 6px 0 0; padding: 8px 10px; font-size: var(--text-xs); }
.msg.compact .msg-meta { font-size: var(--text-xs); }

/* variant="plain" — no bubble at all (use sparingly; prefer Response for long-form) */
.msg.plain .msg-bubble {
  padding: 0;
  border: none;
  background: transparent;
  border-radius: 0;
  font-size: 14px;
}
.msg.plain.user .msg-bubble,
.msg.plain.assistant .msg-bubble {
  background: transparent;
  border: none;
}
.msg.plain .msg-stack { max-width: 100%; }

/* ─── 7. Tool (.tool*) ──────────────────────────────────────────────────────
   Moved from src/ds/migrated/ai/tool.tsx */

.tool {
  width: 100%;
  max-width: 640px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: 10px;
  overflow: hidden;
}

.tool-head {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  padding: 10px 12px;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: start;
  color: var(--fg);
  transition: background var(--dur-fast) var(--ease);
}
.tool-head:hover { background: var(--surface-hover); }
.tool-head:focus-visible { outline: 2px solid var(--ember); outline-offset: -2px; }

.tool-head .ico {
  width: 24px; height: 24px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--surface); border-radius: 5px;
  color: var(--fg-muted);
  flex: 0 0 auto;
  border: 1px solid var(--border);
}
.tool-head .name {
  font: 500 13px/1.3 var(--font-mono);
  color: var(--fg);
  flex: 1; min-width: 0;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.tool-head .name .ns { color: var(--fg-muted); font-weight: 400; }
.tool-head .ms {
  font: 500 11px/1 var(--font-mono);
  color: var(--fg-faint);
  font-feature-settings: 'tnum';
  letter-spacing: 0.02em;
}
.tool-head .chev {
  color: var(--fg-faint);
  transition: transform var(--dur-fast) var(--ease);
}
.tool[data-open="true"] .tool-head .chev { transform: rotate(180deg); }

/* Status pill — alongside the name */
.tool-status {
  display: inline-flex; align-items: center; gap: 5px;
  padding: 3px 8px;
  border-radius: 999px;
  font: 600 10.5px/1 var(--font-mono);
  letter-spacing: 0.06em; text-transform: uppercase;
  border: 1px solid currentColor;
}
.tool-status .dot {
  width: 5px; height: 5px; border-radius: 50%; background: currentColor;
}
.tool-status.pending  { color: var(--status-pending); background: var(--status-pending-soft); border-color: color-mix(in oklab, var(--status-pending) 30%, transparent); }
.tool-status.running  { color: var(--status-running); background: var(--status-running-soft); border-color: color-mix(in oklab, var(--status-running) 30%, transparent); }
.tool-status.done     { color: var(--status-done);    background: var(--status-done-soft);    border-color: color-mix(in oklab, var(--status-done) 30%, transparent); }
.tool-status.error    { color: var(--status-error);   background: var(--status-error-soft);   border-color: color-mix(in oklab, var(--status-error) 30%, transparent); }
.tool-status.running .dot { animation: tool-pulse 1.2s ease-in-out infinite; }
@keyframes tool-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50%      { opacity: 0.4; transform: scale(0.7); }
}

/* Body — collapsed by default */
.tool-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--dur) var(--ease);
  border-top: 1px solid var(--border);
}
.tool[data-open="true"] .tool-body { max-height: 640px; }

.tool-section {
  padding: 10px 12px;
}
.tool-section + .tool-section {
  border-top: 1px dashed var(--border);
}
.tool-section-label {
  display: flex; align-items: center; justify-content: space-between;
  font: 600 10px/1 var(--font-mono);
  letter-spacing: 0.1em; text-transform: uppercase;
  color: var(--fg-subtle);
  margin-bottom: 8px;
}
.tool-section-label .meta {
  color: var(--fg-faint);
  font-weight: 400; letter-spacing: 0.02em;
  text-transform: none;
  font-feature-settings: 'tnum';
}

.tool-code {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 10px 12px;
  font: 400 11.5px/1.55 var(--font-mono);
  color: var(--fg-muted);
  overflow-x: auto;
}
.tool-code .k { color: var(--ember); }
.tool-code .s { color: var(--success); }
.tool-code .n { color: var(--ice); }

.tool-output-text {
  font-size: 13px; line-height: 1.55; color: var(--fg);
}
.tool-output-table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--text-sm);
}
.tool-output-table th, .tool-output-table td {
  padding: 6px 8px;
  border-bottom: 1px solid var(--border);
  text-align: start;
}
.tool-output-table th {
  font-family: var(--font-mono); font-size: var(--text-xs);
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--fg-subtle);
  font-weight: 500;
}
.tool-output-table tr:last-child td { border-bottom: none; }
.tool-output-table td.num {
  font-family: var(--font-mono);
  text-align: end;
  font-feature-settings: 'tnum';
  color: var(--fg);
}

.tool-err {
  display: flex; align-items: flex-start; gap: 8px;
  padding: 10px 12px;
  background: var(--danger-soft);
  border: 1px solid rgba(248,113,113,0.3);
  border-radius: 6px;
  color: var(--danger);
  font-size: var(--text-sm); line-height: 1.5;
}
.tool-err .body { color: var(--fg); }
.tool-err code { background: var(--bg); color: var(--danger); padding: 0 4px; border-radius: 3px; border: 1px solid var(--border); }

/* Skeleton for streaming input */
.tool-skel { display: flex; flex-direction: column; gap: 6px; padding: 4px 0; }
.tool-skel .ln {
  height: 8px; border-radius: 3px;
  background: linear-gradient(90deg, var(--surface-active) 0%, var(--surface-hover) 50%, var(--surface-active) 100%);
  background-size: 200% 100%;
  animation: shimmer 2.6s linear infinite;
}

/* ─── 8. Reasoning (.rsn*) ──────────────────────────────────────────────────
   Moved from src/ds/migrated/ai/reasoning.tsx */

/* Reasoning — flat, no outer box. Same shimmer + timer + auto-close as
   before; trigger sits inline (not full-width) so the chevron lands right
   next to the duration, the way CoT and Sources do it. */
.rsn { background: none; border: 0; border-radius: 0; overflow: visible; width: auto; max-width: 640px; }

/* Trigger — inline, click to toggle. No background, color shifts on hover. */
.rsn-trigger {
  display: inline-flex; align-items: center; gap: 8px;
  width: auto; padding: 0;
  background: none; border: 0;
  color: var(--fg-muted);
  font: 500 13px/1.4 var(--font-sans);
  cursor: pointer; text-align: start;
}
.rsn-trigger:hover { color: var(--fg); }
.rsn-trigger:focus-visible { outline: 2px solid var(--ember); outline-offset: 4px; border-radius: 3px; }

.rsn-trigger .ico {
  width: 22px; height: 22px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ember-soft); color: var(--ember);
  border-radius: 5px;
  flex: 0 0 auto;
}
.rsn-trigger .label {
  flex: 0 0 auto;
  display: inline-flex; align-items: baseline; gap: 6px;
  min-width: 0;
}
.rsn-trigger .label .verb { color: var(--ember); }
.rsn-trigger .dot {
  width: 3px; height: 3px;
  border-radius: 50%; background: var(--fg-faint);
  display: inline-block; flex: 0 0 auto;
}
.rsn-trigger .dur {
  font-family: var(--font-mono);
  font-feature-settings: 'tnum';
  color: var(--fg-faint);
  font-size: var(--text-xs);
}
.rsn-trigger .chev {
  color: var(--fg-faint);
  transition: transform 0.18s ease;
  margin-inline-start: 2px;
  flex: 0 0 auto;
}
.rsn[data-open="true"] .rsn-trigger .chev { transform: rotate(180deg); }

/* Streaming state — shimmer the verb word */
.rsn[data-streaming="true"] .rsn-trigger .verb {
  background: linear-gradient(90deg,
    var(--fg-subtle)  0%,
    var(--ember)     35%,
    var(--ember-glow) 50%,
    var(--ember)     65%,
    var(--fg-subtle) 100%);
  background-size: 220% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  color: transparent;
  animation: shimmer 2.6s linear infinite;
}
.rsn[data-streaming="true"] .rsn-trigger .ico {
  animation: rsn-pulse 1.6s ease-in-out infinite;
}
@keyframes rsn-pulse {
  0%, 100% { box-shadow: 0 0 0 0 var(--ember-soft); }
  50%      { box-shadow: 0 0 0 4px var(--ember-softer); }
}

/* Body — collapsed by default; expands when [data-open=true]. No border
   divider now (no box); the open state breathes via top margin. */
.rsn-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--dur) var(--ease);
}
.rsn[data-open="true"] .rsn-body { max-height: 600px; }

.rsn-body-inner {
  padding: 12px 0 4px;
  font-size: var(--text-base);
  line-height: 1.65;
  color: var(--fg-muted);
  font-family: var(--font-mono);
}
.rsn-body-inner p { margin: 0 0 10px; }
.rsn-body-inner p:last-child { margin-bottom: 0; }
.rsn-body-inner code {
  color: var(--ember);
  background: var(--bg);
  padding: 0 4px; border-radius: 3px;
  border: 1px solid var(--border);
  font-size: var(--text-xs);
}
.rsn-body-inner em {
  color: var(--fg-subtle); font-style: normal;
  font-family: var(--font-sans);
}

/* Skeleton lines used while the reasoning is still arriving */
.rsn-skel { display: flex; flex-direction: column; gap: 6px; }
.rsn-skel .ln {
  height: 9px; border-radius: 3px;
  background: linear-gradient(90deg, var(--surface-active) 0%, var(--surface-hover) 50%, var(--surface-active) 100%);
  background-size: 200% 100%;
  animation: shimmer 2.6s linear infinite;
}

/* Reduced motion — kill the verb shimmer + icon pulse + skeleton shimmer, and
   expand the body instantly. The verb falls back to solid ember (reset the
   gradient text-clip so it stays legible rather than transparent). */
@media (prefers-reduced-motion: reduce) {
  .rsn[data-streaming="true"] .rsn-trigger .verb {
    animation: none;
    background: none;
    -webkit-background-clip: border-box;
    background-clip: border-box;
    color: var(--ember);
  }
  .rsn[data-streaming="true"] .rsn-trigger .ico { animation: none; }
  .rsn-skel .ln { animation: none; }
  .rsn-body { transition: none; }
}

/* ─── 9. Suggestion (.sg* ) ─────────────────────────────────────────────────
   Moved from src/ds/migrated/ai/suggestion.tsx */

/* Suggestion — composes .pill but is a button. The shared shape comes
   from .pill in tokens.css; here we only add interactivity. */
.sg {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 12px;
  font-family: var(--font-sans);
  font-size: var(--text-sm);
  font-weight: 500;
  color: var(--fg-muted);
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  transition: all var(--dur-fast) var(--ease);
}
.sg:hover { background: var(--surface-hover); color: var(--fg); border-color: var(--border-stronger); }
.sg:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }
.sg.is-on, .sg[aria-pressed="true"] {
  color: var(--ember-text);
  background: var(--ember-soft);
  border-color: rgba(255,107,53,0.3);
}
.sg.sm { padding: 4px 10px; font-size: var(--text-xs); }
.sg.lg { padding: 8px 14px; font-size: var(--text-sm); }
.sg .ico { color: var(--fg-faint); }
.sg.is-on .ico { color: var(--ember-text); }
/* Disabled — the browser default dimming is illegible on the dark surface,
   so set an explicit reduced opacity + not-allowed cursor. */
.sg:disabled, .sg[disabled] { opacity: .5; cursor: not-allowed; }

/* Header status chip — Loading "thinking…" / "offline" indicator that the
   FullChatDemo surfaces in the conversation header. Mono eyebrow scale, muted
   by default; the offline state takes the danger-text colour. */
.conv-state {
  display: inline-flex; align-items: center; gap: 6px;
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  color: var(--fg-muted);
}
.conv-state.is-off { color: var(--danger-text); }

/* Row layout — horizontal scroll. Composes the scroll-area look. */
.sg-row {
  display: flex; gap: 8px;
  width: 100%;
  overflow-x: auto;
  padding: 6px 2px 10px;
  -webkit-overflow-scrolling: touch;
  scroll-behavior: smooth;
  scrollbar-width: thin;
}
.sg-row::-webkit-scrollbar { height: 6px; }
.sg-row .sg { flex: 0 0 auto; }

/* Wrap layout */
.sg-wrap { display: flex; flex-wrap: wrap; gap: 8px; }

/* Card layout — slightly bigger tile with icon */
.sg-cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 10px;
  width: 100%;
}
.sg-card {
  display: flex; flex-direction: column;
  gap: 6px;
  padding: 14px 14px 12px;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
  text-align: start;
}
.sg-card:hover {
  background: var(--surface-hover);
  border-color: var(--ember-deep);
  transform: translateY(-1px);
}
.sg-card:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }
.sg-card .ico {
  width: 28px; height: 28px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ember-soft); color: var(--ember);
  border-radius: 6px;
  margin-bottom: 4px;
}
.sg-card .title { font-size: var(--text-sm); font-weight: 600; color: var(--fg); }
.sg-card .line { font-size: 12px; color: var(--fg-muted); line-height: 1.5; }

/* Reduced motion — collapse the card hover lift, the .sg `transition: all`
   background/border tint, and the row smooth-scroll. */
@media (prefers-reduced-motion: reduce) {
  .sg, .sg-card { transition: none; }
  .sg-card:hover { transform: none; }
  .sg-row { scroll-behavior: auto; }
}

/* ─── 10. Prompt input (.pi*) ───────────────────────────────────────────────
   Moved from src/ds/migrated/ai/prompt-input.tsx */

/* Shell — vertical stack so the banner sits inside the bordered .pi and the
   hint reads as a caption below it. width caps on the inner .pi, the shell
   only constrains the column. */
.pi-shell {
  display: flex; flex-direction: column;
  gap: 8px;
  width: 100%; max-width: 720px;
}
.pi-shell > .pi { max-width: none; }

.pi {
  display: flex; flex-direction: column;
  width: 100%; max-width: 720px;
  background: var(--surface);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  transition: border-color var(--dur-fast) var(--ease), box-shadow var(--dur-fast) var(--ease), outline-color var(--dur-fast) var(--ease);
  overflow: hidden;
}
/* Focus ring — canonical DS Core convention (.focus-ring, .btn, .fc-*, .in-*):
   2px solid ember outline with --ring-offset gap. Was previously a 3px soft-glow
   box-shadow which is the surface-input variant (.ds-topbar-search etc) — the
   composer is a primary input, so it gets the documented ring tokens. */
.pi:focus-within {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
  border-color: var(--border-strong);
}
.pi.is-invalid {
  border-color: var(--danger);
}
.pi.is-invalid:focus-within {
  outline-color: var(--ring-danger);
}
.pi.is-dragging {
  border-color: var(--ember);
  background: var(--ember-softer);
}
/* Subtle lift — only --shadow-1 (DS lightest elevation). Kept off the
   default so docs don't ladle gradient bloom over every demo. */
.pi.is-elevated { box-shadow: var(--shadow-1); }
.pi.is-elevated:focus-within { box-shadow: var(--shadow-1); }

/* ── topBanner layout (.pi.has-banner) ──────────────────────────────────────
   The outer .pi keeps its rounded border + focus ring (which therefore wraps
   banner + field together). It paints --bg-elevated as the SOFTER backdrop;
   the banner sits flush at the top with transparent bg, and a nested
   .pi-field below is the brighter --surface input area with rounded TOP
   corners only — its sides + bottom are flush against .pi's border, so the
   shoulder-rounding shows ONLY on the top edge. No outer padding, no gap. */
.pi.has-banner {
  background: var(--bg-elevated);
}

.pi-field {
  display: flex; flex-direction: column;
  background: var(--surface);
  border-top: 1px solid var(--border);
  border-radius: 12px 12px 0 0;
}

/* Top banner — ribbon at the TOP of the .pi shell. Transparent so the
   --bg-elevated of .pi shows through (matching the input's softer top
   shoulder). No border-bottom — the visual separator is the colour break
   between the banner (bg-elevated) and the .pi-field (surface) plus the
   .pi-field's rounded top edge. */
.pi-banner {
  display: flex; align-items: center; gap: 10px;
  padding: 9px 14px;
  background: transparent;
  font-size: var(--text-xs); color: var(--fg-muted);
  font-family: var(--font-mono); letter-spacing: 0.02em;
}
/* Banner inner elements — rendered by <PromptBanner/> as direct flex
   children of .pi-banner. Tone is per-child (icon + CTA), so the slot can
   also accept plain text or arbitrary children without forcing a tone. */
.pi-banner-icon {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 18px; block-size: 18px;
  color: var(--ember);
  flex: 0 0 auto;
}
.pi-banner-icon.tone-promo   { color: var(--ember); }
.pi-banner-icon.tone-info    { color: var(--fg-muted); }
.pi-banner-icon.tone-warn    { color: var(--warning, #FBBF24); }
.pi-banner-icon.tone-success { color: var(--success, #34D399); }
.pi-banner-icon.tone-danger  { color: var(--danger, #FF453A); }

.pi-banner-text { min-inline-size: 0; }
.pi-banner-text b, .pi-banner-text strong { color: var(--fg); font-weight: 600; }

/* Banner CTA — ALWAYS ember (DS standard link colour). Tone tints only the
   icon; the action affordance keeps its single accent so it stays
   recognisable across tones and inside the 2× ember-per-screen budget. */
.pi-banner a,
.pi-banner-cta {
  background: transparent; border: 0; padding: 0; cursor: pointer;
  font: inherit; font-weight: 600;
  color: var(--ember); text-decoration: none;
  margin-inline-start: auto;
  display: inline-flex; align-items: center; gap: 4px;
  flex: 0 0 auto;
}
.pi-banner a:hover, .pi-banner-cta:hover { text-decoration: underline; }

/* Dismiss × — neutral, sits last. When a CTA is also present, the CTA is
   margin-inline-start: auto so it pushes everything after it (including the
   ×) to the trailing edge — the × loses the auto-margin (already pushed). */
.pi-banner-x {
  inline-size: 20px; block-size: 20px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: 0; border-radius: 4px;
  color: var(--fg-subtle); cursor: pointer;
  flex: 0 0 auto;
  margin-inline-start: 4px;
  transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);
}
.pi-banner-x:hover { background: var(--surface-hover); color: var(--fg); }
.pi-banner-x:focus-visible { outline: 1px solid var(--ember); outline-offset: 1px; }
/* When NO CTA is present, the × itself takes the trailing-edge slot. */
.pi-banner > .pi-banner-x:only-of-type { margin-inline-start: auto; }

/* Footer hint — supporting text BELOW the bordered .pi. Centred, muted,
   small. Use for legal / disclaimer copy. */
.pi-hint {
  text-align: center;
  font-size: var(--text-xs); line-height: 1.45;
  color: var(--fg-faint);
  padding-inline: 8px;
}

/* Header — attachments preview row, only when attachments are present */
.pi-head {
  display: flex; flex-wrap: wrap; gap: 6px;
  padding: 10px 12px 0;
}
.pi-att {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 4px 6px 4px 4px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  font-size: 12px;
  color: var(--fg-muted);
  max-width: 200px;
}
.pi-att .thumb {
  width: 26px; height: 26px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--surface); border-radius: 5px;
  color: var(--fg-subtle);
  flex: 0 0 auto;
}
.pi-att .name {
  color: var(--fg); font-weight: 500;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
  min-width: 0;
}
.pi-att .close {
  width: 18px; height: 18px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: none; border-radius: 4px;
  color: var(--fg-subtle); cursor: pointer;
}
.pi-att .close:hover { background: var(--surface-hover); color: var(--fg); }

/* Body — textarea */
.pi-body {
  padding: 10px 14px;
}
.pi-textarea {
  width: 100%;
  min-height: 24px;
  max-height: 220px;
  resize: none;
  background: transparent;
  border: none;
  outline: none;
  color: var(--fg);
  font: 400 14px/1.55 var(--font-sans);
  padding: 4px 0;
  font-feature-settings: 'tnum';
}
.pi-textarea::placeholder { color: var(--fg-faint); }

/* Footer — toolbar */
.pi-foot {
  display: flex; align-items: center; gap: 6px;
  padding: 6px 8px 8px;
}
.pi-tool {
  width: 32px; height: 32px;
  display: inline-flex; align-items: center; justify-content: center;
  background: transparent; border: 1px solid transparent;
  border-radius: 8px;
  color: var(--fg-subtle); cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.pi-tool:hover { background: var(--surface-hover); color: var(--fg); }
.pi-tool:focus-visible {
  outline: 2px solid var(--ember);
  outline-offset: 1px;
}
.pi-tool.is-on { color: var(--ember); background: var(--ember-soft); }

/* Model picker — disguised .btn.outline */
.pi-model {
  display: inline-flex; align-items: center; gap: 8px;
  height: 32px; padding: 0 10px 0 8px;
  background: transparent; border: 1px solid var(--border-strong);
  border-radius: 8px;
  font: 500 12px/1 var(--font-sans);
  color: var(--fg-muted); cursor: pointer;
  transition: all var(--dur-fast) var(--ease);
}
.pi-model:hover { color: var(--fg); background: var(--surface-hover); border-color: var(--border-stronger); }
.pi-model .badge {
  width: 18px; height: 18px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ember-soft); color: var(--ember);
  border-radius: 4px;
}
.pi-model .name { color: var(--fg); font-weight: 500; }
.pi-foot .spacer { flex: 1; }

/* Submit — variants. Default is a SOFT ember tint (ember-soft fill + ember
   icon), not a loud solid ember fill — the composer is a single field on
   screen and a screaming-orange button reads as marketing chrome. The hover
   ramps to solid ember (the "I'm about to send" moment), which keeps the
   accent signal where it counts without burning the ember budget at rest. */
.pi-submit {
  width: 32px; height: 32px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ember-soft); color: var(--ember);
  border: 1px solid color-mix(in oklab, var(--ember) 22%, transparent);
  border-radius: 8px;
  cursor: pointer;
  transition: background var(--dur-fast) var(--ease), border-color var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease), transform var(--dur-fast) var(--ease);
}
.pi-submit:hover:not(:disabled) {
  background: var(--ember); border-color: var(--ember); color: var(--ember-fg);
  transform: translateY(-1px);
}
.pi-submit:disabled {
  background: var(--surface-active); color: var(--fg-faint);
  border-color: var(--border); cursor: not-allowed; transform: none;
}
.pi-submit.is-streaming { background: var(--fg); border-color: var(--fg); color: var(--bg); }
.pi-submit.is-streaming:hover { background: var(--fg-muted); border-color: var(--fg-muted); }
.pi-submit.is-submitted {
  background: var(--surface); color: var(--fg-subtle);
  border-color: var(--border-strong); cursor: progress;
}
.pi-submit.is-error {
  background: var(--danger-soft); color: var(--danger);
  border-color: color-mix(in oklab, var(--danger) 22%, transparent);
}
.pi-submit.is-error:hover { background: var(--danger); border-color: var(--danger); color: #fff; }
.pi-submit-spin {
  width: 14px; height: 14px;
  border: 1.5px solid currentColor;
  border-top-color: transparent;
  border-radius: 50%;
  animation: pi-spin 0.8s linear infinite;
}
@keyframes pi-spin { to { transform: rotate(360deg); } }

/* Drop-zone hint */
.pi-drop-hint {
  display: flex; align-items: center; justify-content: center;
  gap: 8px;
  padding: 18px;
  border-top: 1px dashed var(--border-strong);
  font-family: var(--font-mono); font-size: var(--text-xs);
  color: var(--ember); letter-spacing: 0.04em;
}

/* Drop overlay — full-shell ember veil while a file is hovering */
.pi-drop-overlay {
  position: absolute; inset: 0; z-index: 5;
  display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  gap: 8px;
  background: rgba(255,107,53,0.08);
  border: 2px dashed var(--ember);
  border-radius: 14px;
  pointer-events: none;
  color: var(--ember);
  font: 600 13px/1.3 var(--font-sans);
  letter-spacing: -0.005em;
}
.pi-drop-overlay .sub {
  font: 400 11.5px/1 var(--font-mono);
  color: var(--fg-muted);
  letter-spacing: 0.04em;
}

/* Image attachment — show a 40×40 preview thumb instead of the file icon */
.pi-att.image { padding: 4px 8px 4px 4px; }
.pi-att.image .thumb {
  width: 40px; height: 40px;
  background: var(--surface);
  border-radius: 6px;
  overflow: hidden;
}
.pi-att.image .thumb img,
.pi-att.image .thumb svg {
  width: 100%; height: 100%;
  object-fit: cover; display: block;
}
.pi-att .meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.pi-att .meta .sz {
  font-family: var(--font-mono); font-size: 10px;
  color: var(--fg-faint);
}

/* Upload progress on an attachment — slim ember bar across the bottom */
.pi-att.is-uploading { background: var(--surface); }
.pi-att .progress {
  position: absolute; left: 4px; right: 4px; bottom: 2px;
  height: 2px; background: var(--bg);
  border-radius: 1px; overflow: hidden;
}
.pi-att { position: relative; }
.pi-att .progress > span {
  display: block; height: 100%;
  background: var(--ember);
  transition: width var(--dur-fast) var(--ease);
}

/* Helper text below the input (off-shell) */
.pi-helper {
  display: flex; justify-content: space-between; align-items: center;
  margin-top: 6px; padding: 0 6px;
  font-size: var(--text-xs); color: var(--fg-faint);
}
.pi-kbd-row { display: inline-flex; gap: 4px; align-items: center; }
.pi-kbd-label { font-size: var(--text-xs); color: var(--fg-faint); margin-inline: 4px; }
.pi-kbd-sep { color: var(--border-strong); margin-inline: 6px; font-size: var(--text-xs); }
.pi-kbd {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 18px; height: 17px; padding: 0 4px;
  background: var(--bg-elevated); border: 1px solid var(--border-strong);
  border-bottom-width: 2px;
  border-radius: 4px; color: var(--fg-muted);
  font: 600 10px/1 var(--font-mono);
}

/* Model menu popover */
.pi-menu {
  position: absolute; z-index: 30;
  min-width: 220px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 4px;
  box-shadow: 0 12px 32px rgba(0,0,0,0.42);
}
.pi-menu-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: 5px;
  font-size: var(--text-sm); color: var(--fg);
  cursor: pointer; white-space: nowrap;
}
.pi-menu-item:hover { background: var(--surface-hover); }
.pi-menu-item .sub { color: var(--fg-subtle); font-size: 11px; font-family: var(--font-mono); margin-inline-start: auto; }
.pi-menu-item.is-active { background: var(--ember-soft); color: var(--ember); }

/* ─── 11. Conversation (.conv*) ─────────────────────────────────────────────
   Moved from src/ds/migrated/ai/conversation.tsx */

/* The shell — sized container, scrollable body, sticky footer slot. */
.conv {
  display: flex; flex-direction: column;
  width: 100%; max-width: 720px;
  height: 420px;
  border: 1px solid var(--border);
  border-radius: 12px;
  background: var(--bg);
  overflow: hidden;
  position: relative;
}
.conv.tall { height: 520px; }
.conv-head {
  display: flex; align-items: center; gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-elevated);
  font-size: var(--text-sm); color: var(--fg-muted);
}
.conv-head .title { color: var(--fg); font-weight: 500; font-size: 13px; }
.conv-count { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint); font-variant-numeric: tabular-nums; }
.conv-head .spacer { flex: 1; }

.conv-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--ai-thread-pad-block) var(--ai-thread-pad-inline);
  display: flex; flex-direction: column;
  scroll-behavior: smooth;
}
.conv-body::-webkit-scrollbar { width: 10px; }

/* The .msg-* styles live in ai.css (section 6), and the page
   uses <Message variant="compact"/> to consume them. */

/* The canonical <Empty/> primitive (atoms.tsx + .empty-* in ds.css) stretches
   vertically inside the scroll body. */
.conv-body .empty { flex: 1; }

/* Floating "jump to latest" pill — appears when scroll position is not at bottom */
.conv-jump {
  position: absolute;
  bottom: 14px; inset-inline-end: 14px;
  z-index: 5;
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 10px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: 999px;
  color: var(--fg-muted);
  font: 500 11.5px/1 var(--font-sans);
  cursor: pointer;
  box-shadow: 0 6px 20px rgba(0,0,0,0.32);
  transition: all var(--dur-fast) var(--ease);
}
.conv-jump:hover { color: var(--fg); border-color: var(--border-stronger); transform: translateY(-1px); }
.conv-jump:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }
.conv-jump .n {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 18px; height: 18px; padding: 0 5px;
  background: var(--ember); color: var(--ember-fg); font-weight: 700;
  border-radius: 999px; font-size: var(--text-xs); font-family: var(--font-mono);
}
/* Arrow-only variant — shown when not at bottom but with no unread.
   A small round button with just the chevron-down icon, perfectly
   centred (the base .conv-jump uses inline-flex without justify-content,
   so a single child would otherwise sit at the leading edge). */
.conv-jump.is-bare {
  inline-size: 32px; block-size: 32px;
  padding: 0; gap: 0;
  justify-content: center;
  background: var(--bg-elevated); border-color: var(--border);
  color: var(--fg-muted);
}
.conv-jump.is-bare:hover { color: var(--ember); border-color: var(--ember); }
.conv-jump.is-bare:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }

/* Docked footer area — suggestions row + prompt input — lives INSIDE the
   .conv container so the input belongs to the chat, not floats below it.
   Background MATCHES the chat (var(--bg)) — no hard divider line; instead
   a gradient fade above lets the last messages dissolve INTO the foot,
   the way the code-block "Show code" button is approached from above. */
.conv-foot {
  flex: 0 0 auto;
  display: flex; flex-direction: column; gap: 10px;
  padding: 14px;
  background: var(--bg);
  position: relative;
  z-index: 1;
}
.conv-foot::before {
  content: '';
  position: absolute;
  inset-inline: 0;
  bottom: 100%;
  block-size: 40px;
  background: linear-gradient(to top, var(--bg) 0%, transparent 100%);
  pointer-events: none;
}
.conv-sgg {
  display: flex; flex-wrap: wrap; gap: 6px;
}
/* The PromptInput inside conv-foot fills the row. */
.conv-foot .pi { max-width: none; }

/* ─── mode="document" — ChatGPT-style long-form thread ────────────────── */
/* Document mode — ChatGPT-style long-form thread. Background is the
   elevated surface so the document reads as its OWN surface rather than
   merging with the page; the prose breathes against it. */
.conv.mode-document { max-width: 940px; background: var(--bg-elevated); }
.conv.mode-document .conv-body {
  padding: 28px 32px 36px;
  gap: 32px;
}
/* User question keeps a compact bubble alignment-trailing.
   Assistant turn is a full Response — no bubble, prose-scale. */
.conv-doc-q {
  display: flex; justify-content: flex-end;
}
[dir="rtl"] .conv-doc-q { justify-content: flex-start; }
.conv-doc-q-bubble {
  padding: 10px 14px;
  background: var(--ember-soft);
  border: 1px solid rgba(255,107,53,0.22);
  border-radius: 12px;
  color: var(--fg);
  font-size: 14px;
  line-height: 1.55;
  max-width: 72%;
  word-wrap: break-word;
}
.conv-doc-a-meta {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--font-mono); font-size: var(--text-xs);
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--fg-subtle);
  margin-bottom: 10px;
}
.conv-doc-a-meta .name {
  color: var(--fg-muted);
  text-transform: none; letter-spacing: 0;
  font-size: 12px; font-family: var(--font-sans); font-weight: 500;
}
.conv-doc-a-meta .dot { width: 3px; height: 3px; border-radius: 50%; background: var(--fg-faint); }

/* Quiet divider between assistant turn and next user turn — only in document mode */
.conv.mode-document .conv-doc-divider {
  height: 1px;
  background: var(--border);
  margin: 4px 0 0;
}

/* ─── 12. AI Label (.ai-label* / .ai-pop*) ──────────────────────────────────
   Moved from src/ds/migrated/ai/label.tsx (AI_CSS const) */

.ai-label {
  display: inline-flex; align-items: center; gap: 4px;
  font-family: var(--font-mono); font-weight: 600;
  letter-spacing: 0.04em; font-size: 11px; line-height: 1;
  color: var(--ember); vertical-align: middle; user-select: none;
}
.ai-label .ai-glyph { display: inline-flex; flex: 0 0 auto; }
.ai-label .ai-glyph svg { width: 10px; height: 10px; display: block; }
.ai-label.box {
  width: 22px; height: 22px;
  border: 1px solid currentColor; border-radius: 4px;
  justify-content: center; gap: 0;
}
.ai-label.box .ai-glyph { display: none; }
.ai-label.box .ai-text { font-size: 9px; }
.ai-label.pill {
  padding-block: 3px; padding-inline-start: 6px; padding-inline-end: 8px;
  border: 1px solid rgba(255, 107, 53, 0.3);
  background: var(--ember-soft);
  border-radius: 999px;
}
.ai-label.dot { gap: 0; }
.ai-label.dot .ai-text { display: none; }
.ai-label.dot .ai-glyph svg { width: 12px; height: 12px; }
.ai-label.sm { font-size: 10px; gap: 3px; }
.ai-label.sm.box { width: 18px; height: 18px; border-radius: 3px; }
.ai-label.sm.box .ai-text { font-size: 8px; }
.ai-label.sm .ai-glyph svg { width: 8px; height: 8px; }
.ai-label.sm.pill { padding-block: 2px; padding-inline-start: 5px; padding-inline-end: 7px; }
.ai-label.lg { font-size: var(--text-sm); gap: 5px; }
.ai-label.lg.box { width: 28px; height: 28px; border-radius: 5px; }
.ai-label.lg.box .ai-text { font-size: 11px; }
.ai-label.lg .ai-glyph svg { width: 13px; height: 13px; }
.ai-label.lg.pill { padding-block: 4px; padding-inline-start: 8px; padding-inline-end: 10px; }
.ai-label.revoked { color: var(--fg-faint); }
.ai-label.revoked .ai-text { text-decoration: line-through; }
.ai-label.revoked.box { border-color: var(--fg-faint); }
.ai-label.revoked.pill { background: transparent; border-color: var(--border-strong); }
.ai-label.is-trigger {
  cursor: pointer; outline: none;
  transition: background-color var(--dur-fast) var(--ease);
}
.ai-label.pill.is-trigger:hover { background: rgba(255, 107, 53, 0.2); }
.ai-label.is-trigger:focus-visible {
  box-shadow: 0 0 0 2px var(--bg), 0 0 0 4px var(--ember);
  border-radius: 4px;
}
/* Reduced motion — collapse the interactive pill's background-color transition
   to an instant colour change. */
@media (prefers-reduced-motion: reduce) {
  .ai-label.is-trigger { transition: none; }
}
.ai-pop-anchor { position: relative; display: inline-block; }
.ai-pop {
  position: absolute; top: calc(100% + 8px); inset-inline-start: 0; z-index: 30;
  width: 280px; padding: 12px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong); border-radius: 8px;
  box-shadow: var(--elev-3);
  font-family: var(--font);
}
.ai-pop-head {
  display: flex; align-items: center; gap: 8px;
  font-size: var(--text-sm); font-weight: 600; color: var(--fg);
}
.ai-pop-desc {
  font-size: 12px; color: var(--fg-muted);
  margin-top: 6px; line-height: 1.55;
}
.ai-pop-meta {
  margin: 10px 0 0; padding-top: 10px;
  border-top: 1px dashed var(--border);
  display: grid; grid-template-columns: auto 1fr; gap: 4px 12px;
}
.ai-pop-meta dt {
  font-family: var(--font-mono); font-size: 10px;
  letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--fg-subtle); margin: 0;
}
.ai-pop-meta dd {
  font-family: var(--font-mono); font-size: var(--text-xs);
  font-variant-numeric: tabular-nums;
  color: var(--fg); margin: 0;
}
.ai-pop-actions { display: flex; gap: 6px; margin-top: 10px; }

/* ════════════════════════════════════════════════════════════════════════
   Agent identity — AgentAvatar / AgentIdentity (core/ai/identity.tsx)
   The avatar reuses .avatar/.avatar.ember + .status-dot from tokens.css;
   only the glyph-centering + the inline identity row are defined here.
   ════════════════════════════════════════════════════════════════════════ */
.ai-agent-avatar { border-radius: var(--radius-lg); }
.ai-agent-avatar svg { display: block; }

.ai-agent-id {
  display: inline-flex; align-items: center; gap: 10px;
  min-width: 0;
}
.ai-agent-id-text {
  display: inline-flex; flex-direction: column; gap: 1px; min-width: 0;
}
.ai-agent-id-name {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: var(--text-sm); font-weight: 600; color: var(--fg);
  line-height: 1.2;
}
.ai-agent-id-model {
  font-family: var(--font-mono); font-size: var(--text-xs);
  color: var(--fg-muted); line-height: 1.2;
}

/* ════════════════════════════════════════════════════════════════════════
   Content blocks — Shimmer / Skeleton / ImageView / Math (core/ai/content.tsx)
   (.ai-diagram already defined above, reused by <Diagram/>.)
   ════════════════════════════════════════════════════════════════════════ */

/* Shimmer — gradient sweep over text while the model thinks */
.ai-shimmer {
  background: linear-gradient(100deg,
    var(--fg-faint) 30%, var(--fg) 50%, var(--fg-faint) 70%);
  background-size: 200% 100%;
  -webkit-background-clip: text; background-clip: text;
  color: transparent;
  animation: ai-shimmer-sweep 2.6s linear infinite;
  font-size: var(--text-sm);
}
@keyframes ai-shimmer-sweep {
  from { background-position: 200% 0; }
  to   { background-position: -200% 0; }
}

/* Skeleton — retired from ai.css. The canonical .sk / .sk-shimmer system
   now lives in ds.css. <Skeleton lines={N}/> from packages/ui/src/skeleton.tsx
   renders the stacked bars previously handled by .ai-skel / .ai-skel-line. */

/* ImageView — bordered, rounded image in a reply */
.ai-image { margin: 0; display: inline-flex; flex-direction: column; gap: 8px; }
.ai-image-frame {
  position: relative; overflow: hidden;
  border: 1px solid var(--border); border-radius: var(--radius-lg);
  background: var(--surface); min-height: 64px;
}
.ai-image.square .ai-image-frame { border-radius: var(--radius-md); }
.ai-image-frame img {
  display: block; width: 100%; height: 100%; object-fit: cover;
  transition: opacity 0.3s ease;
}
.ai-image-shimmer {
  position: absolute; inset: 0;
  background: linear-gradient(100deg,
    var(--surface) 30%, var(--surface-active) 50%, var(--surface) 70%);
  background-size: 200% 100%;
  animation: ai-shimmer-sweep 2.6s linear infinite;
}
.ai-image-fallback {
  position: absolute; inset: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 6px; color: var(--fg-faint); font-size: var(--text-xs);
  font-family: var(--font-mono);
}
.ai-image figcaption {
  font-family: var(--font-mono); font-size: var(--text-xs);
  color: var(--fg-muted); line-height: 1.5;
}

/* Math — KaTeX render target */
.ai-math { font-size: 1.02em; line-height: 1.4; }
.ai-math.block {
  display: block; margin-block: 16px; overflow-x: auto;
  text-align: center; padding-block: 4px;
}
.ai-math .katex-display { margin: 0; }

/* CJK — Chinese/Japanese/Korean prose handling: looser line-height, no mid-
   word breaking of Latin runs, and a system CJK font fallback. */
.ai-prose:lang(zh), .ai-prose:lang(ja), .ai-prose:lang(ko),
.msg-bubble:lang(zh), .msg-bubble:lang(ja), .msg-bubble:lang(ko) {
  line-height: 1.85;
  letter-spacing: 0;
  word-break: normal;
  overflow-wrap: anywhere;
  line-break: strict;
}
.ai-prose:lang(ja), .msg-bubble:lang(ja) {
  font-family: var(--font), 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
}
.ai-prose:lang(zh), .msg-bubble:lang(zh) {
  font-family: var(--font), 'PingFang SC', 'Hiragino Sans GB', 'Microsoft YaHei', sans-serif;
}
.ai-prose:lang(ko), .msg-bubble:lang(ko) {
  font-family: var(--font), 'Apple SD Gothic Neo', 'Malgun Gothic', sans-serif;
}
/* Korean — keep eojeol/syllable blocks intact (keep-all), while
   overflow-wrap:anywhere still lets long compounds/URLs break. */
.ai-prose:lang(ko), .msg-bubble:lang(ko) { word-break: keep-all; }

@media (prefers-reduced-motion: reduce) {
  .ai-shimmer, .ai-image-shimmer { animation: none; }
  .ai-shimmer { background: none; -webkit-background-clip: border-box; background-clip: border-box; color: var(--fg-muted); }
}

/* ════════════════════════════════════════════════════════════════════════
   Agentic — ChainOfThought / Plan / Task / Checkpoint / Confirmation / Queue
   (core/ai/agentic.tsx) + Ask (core/ai/ask.tsx)
   ════════════════════════════════════════════════════════════════════════ */

/* ── ChainOfThought — flat, typographic. No box. ── */
.ai-cot { background: none; border: 0; padding: 0; }
.ai-cot-head {
  display: inline-flex; align-items: center; gap: 7px;
  background: none; border: 0; padding: 0; cursor: pointer;
  font-family: var(--font-mono); font-size: var(--text-xs);
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--fg-muted); text-align: start;
}
.ai-cot-head:hover { color: var(--fg); }
.ai-cot-head:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; border-radius: 3px; }
.ai-cot-head .ico { display: none; }
.ai-cot-head .label { color: var(--ember); font-weight: 500; }
.ai-cot-head .count { color: var(--fg-faint); margin-inline-start: 4px; }
.ai-cot-head .count::before { content: '· '; color: var(--fg-faint); }
.ai-cot-head .chev { color: var(--fg-faint); transition: transform 0.18s ease; margin-inline-end: 2px; }
.ai-cot[data-open="true"] .ai-cot-head .chev { transform: rotate(180deg); }
.ai-cot-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.22s ease; }
.ai-cot[data-open="true"] .ai-cot-body { grid-template-rows: 1fr; }
.ai-cot-steps {
  overflow: hidden; list-style: none; margin: 12px 0 0; padding: 0;
  display: flex; flex-direction: column; gap: 12px;
}
.ai-cot-step { display: flex; gap: 11px; padding: 0; position: static; }
.ai-cot-step::before { display: none; }
.ai-cot-mark {
  flex: 0 0 auto; width: 16px; height: 16px; padding-top: 2px;
  display: inline-flex; align-items: flex-start; justify-content: center;
  background: none; border: 0; color: var(--fg-faint); border-radius: 0;
}
.ai-cot-step[data-status="active"] .ai-cot-mark { color: var(--ember); }
.ai-cot-step[data-status="done"] .ai-cot-mark { color: var(--fg-muted); }
.ai-cot-content { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.ai-cot-label { font-size: var(--text-sm); color: var(--fg); line-height: 1.5; }
.ai-cot-detail { font-size: var(--text-base); color: var(--fg-muted); line-height: 1.55; }

/* ── Plan ── */
.ai-plan { border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface); }
.ai-plan-head { display: flex; align-items: center; gap: 8px; padding: 10px 12px; border-bottom: 1px solid var(--border); }
.ai-plan-head .ico { color: var(--ember); display: inline-flex; }
.ai-plan-head .label { font-weight: 600; font-size: var(--text-sm); }
.ai-plan-head .count { margin-inline-start: auto; font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint); }
.ai-plan-list { list-style: none; margin: 0; padding: 6px; display: flex; flex-direction: column; gap: 2px; }
.ai-plan-item { display: flex; gap: 10px; padding: 7px 8px; border-radius: var(--radius-md); align-items: flex-start; }
.ai-plan-item[data-status="active"] { background: var(--ember-soft); }
.ai-plan-mark {
  flex: 0 0 auto; width: 20px; height: 20px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  font-family: var(--font-mono); font-size: 10px;
  background: var(--surface-active); border: 1px solid var(--border); color: var(--fg-muted);
}
.ai-plan-item[data-status="done"] .ai-plan-mark { background: var(--success-soft, rgba(52,199,89,0.14)); border-color: rgba(52,199,89,0.4); color: var(--success); }
.ai-plan-item[data-status="active"] .ai-plan-mark { background: none; border: 0; }
.ai-plan-item[data-status="done"] .ai-plan-title { color: var(--fg-muted); text-decoration: line-through; text-decoration-color: var(--border-strong); }
.ai-plan-title { font-size: var(--text-sm); color: var(--fg); line-height: 1.45; }
.ai-plan-detail { font-size: var(--text-xs); color: var(--fg-muted); margin-top: 2px; }

/* ── Task ── */
.ai-task { border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface); padding: 10px 12px; }
.ai-task-head { display: flex; align-items: center; gap: 9px; }
.ai-task-title { font-size: var(--text-sm); font-weight: 600; color: var(--fg); }
.ai-task[data-status="done"] .ai-task-title { color: var(--fg-muted); }
.ai-task-detail { margin-inline-start: auto; font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-muted); }
.ai-task-mark { flex: 0 0 auto; width: 18px; height: 18px; display: inline-flex; align-items: center; justify-content: center; color: var(--fg-muted); }
.ai-task[data-status="done"] .ai-task-mark { color: var(--success); }
.ai-task[data-status="error"] .ai-task-mark { color: var(--danger); }
.ai-task-mark.sm { width: 15px; height: 15px; }
.ai-task-dot { width: 7px; height: 7px; border-radius: 50%; border: 1.5px solid var(--border-strong); }
.ai-task-subs { list-style: none; margin: 8px 0 0; padding: 0 0 0 27px; display: flex; flex-direction: column; gap: 5px; }
.ai-task-sub { display: flex; align-items: center; gap: 8px; font-size: var(--text-base); color: var(--fg-muted); }
.ai-task-sub[data-status="done"] { color: var(--fg-subtle); text-decoration: line-through; text-decoration-color: var(--border-strong); }

/* ── Checkpoint — flat: hairline + inline mono label, no chip ── */
.ai-checkpoint { display: flex; align-items: center; gap: 12px; margin-block: 20px; }
.ai-checkpoint-rule { flex: 1; height: 1px; background: var(--border); }
.ai-checkpoint-label {
  display: inline-flex; align-items: center; gap: 8px;
  font-family: var(--font-mono); font-size: var(--text-xs);
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--fg-faint);
}
.ai-checkpoint-label .lbl { color: var(--fg); font-weight: 500; }
.ai-checkpoint-label .flag-mark { color: var(--ember); flex: none; }
.ai-checkpoint-label .sep { color: var(--fg-faint); }
.ai-checkpoint-label .t { color: var(--fg-faint); text-transform: none; letter-spacing: 0; }
.ai-checkpoint-restore {
  background: none; border: 0; padding: 0; margin-inline-start: 4px;
  color: var(--fg-muted); font-family: var(--font-mono); font-size: var(--text-xs);
  text-transform: uppercase; letter-spacing: 0.08em; cursor: pointer;
}
.ai-checkpoint-restore:hover { color: var(--ember); text-decoration: underline; }
.ai-checkpoint-restore:focus-visible { outline: var(--ring-width) solid var(--ring); outline-offset: 2px; border-radius: 3px; }

/* ── Confirmation ── */
.ai-confirm { border: 1px solid var(--border-strong); border-radius: var(--radius-lg); background: var(--surface); padding: 12px 14px; max-width: 460px; }
.ai-confirm[data-tone="danger"] { border-color: rgba(255,69,58,0.35); background: var(--danger-soft, rgba(255,69,58,0.08)); }
.ai-confirm-body { display: flex; gap: 10px; }
.ai-confirm-ico { flex: 0 0 auto; color: var(--ember); margin-top: 1px; }
.ai-confirm[data-tone="danger"] .ai-confirm-ico { color: var(--danger); }
.ai-confirm-title { font-size: var(--text-sm); font-weight: 600; color: var(--fg); }
.ai-confirm-msg { font-size: var(--text-base); color: var(--fg-muted); line-height: 1.5; margin-top: 3px; }
.ai-confirm-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 12px; }
.ai-confirm-result {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 10px;
  font-family: var(--font-mono); font-size: var(--text-xs);
}
.ai-confirm-result[data-state="confirmed"] { color: var(--success); }
.ai-confirm-result[data-state="cancelled"] { color: var(--fg-muted); }

/* ── Queue ── */
.ai-queue { border: 1px solid var(--border); border-radius: var(--radius-lg); background: var(--surface); }
.ai-queue-head { display: flex; align-items: center; gap: 7px; padding: 9px 12px; border-bottom: 1px solid var(--border); color: var(--fg-muted); font-size: var(--text-xs); font-family: var(--font-mono); text-transform: uppercase; letter-spacing: 0.06em; }
.ai-queue-head .count { margin-inline-start: auto; color: var(--fg-faint); font-variant-numeric: tabular-nums; }
.ai-queue-list { list-style: none; margin: 0; padding: 6px; display: flex; flex-direction: column; gap: 2px; }
.ai-queue-item { display: flex; align-items: center; gap: 10px; padding: 7px 8px; border-radius: var(--radius-md); }
.ai-queue-item:hover { background: var(--surface-active); }
.ai-queue-pos { flex: 0 0 auto; width: 18px; height: 18px; border-radius: 50%; background: var(--surface-active); border: 1px solid var(--border); display: inline-flex; align-items: center; justify-content: center; font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-muted); font-variant-numeric: tabular-nums; }
.ai-queue-text { flex: 1; font-size: var(--text-base); color: var(--fg); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ai-queue-remove { flex: 0 0 auto; background: none; border: 0; color: var(--fg-faint); cursor: pointer; display: inline-flex; padding: 2px; border-radius: 4px; }
.ai-queue-remove:hover { color: var(--danger); background: var(--surface); }

/* ════════════════════════════════════════════════════════════════════════
   AskUser — clean-room rebuild after fluidfunctionalism.com.
   Sans throughout (no mono uppercase eyebrows). Borderless. Big confident
   title. Options as flat rows separated by whitespace. Selection = a quiet
   ember-soft fill. Title stays var(--fg) on select — the fill is the cue.
   ════════════════════════════════════════════════════════════════════════ */
.ask { background: none; border: 0; padding: 0; max-width: 560px; outline: none; overflow: hidden; }

/* Question — keyed by step, remounts on change. CSS @keyframes drive
   the slide entry from right ("next" direction) or left ("prev"). */
.ask-q { animation: ask-slide-next 0.24s var(--ease, cubic-bezier(0.22,0.61,0.36,1)) both; }
.ask.is-prev .ask-q { animation-name: ask-slide-prev; }
@keyframes ask-slide-next {
  from { transform: translateX(28px); opacity: 0; }
  to   { transform: translateX(0);    opacity: 1; }
}
@keyframes ask-slide-prev {
  from { transform: translateX(-28px); opacity: 0; }
  to   { transform: translateX(0);     opacity: 1; }
}

/* Header row — topic + "Question N of M" on the leading edge, progress
   bar pushed to the trailing edge (where Skip used to live; Skip moved
   to the footer next to Continue). */
.ask-q-head {
  display: flex; align-items: center; gap: 8px; margin-bottom: 12px;
  font-size: var(--text-xs); color: var(--fg-faint); line-height: 1.4;
}
.ask-q-topic { color: var(--ember); font-weight: 500; }
.ask-q-topic + .ask-q-step::before { content: '·'; color: var(--fg-faint); margin-inline-end: 6px; }
.ask-q-step { color: var(--fg-faint); }

/* Progress — 80px × 2px on the trailing edge. */
.ask-q-progress {
  margin-inline-start: auto;
  display: inline-block; inline-size: 80px; block-size: 2px;
  background: var(--surface); border-radius: 999px; overflow: hidden;
}
.ask-q-progress-fill {
  display: block; block-size: 100%; background: var(--ember);
  border-radius: 999px;
  transition: inline-size 0.32s ease;
}

/* Skip — text-link sitting in the footer LEFT of Continue. */
.ask-q-skip {
  background: none; border: 0; padding: 0;
  color: var(--fg-muted); font: inherit; font-size: var(--text-sm); cursor: pointer;
  transition: color 0.14s ease;
}
.ask-q-skip:hover { color: var(--ember); text-decoration: underline; }
.ask-q-skip:disabled { opacity: 0.4; cursor: not-allowed; }

/* Title — confident, sans semibold, light tracking. */
.ask-q-title {
  margin: 0 0 18px;
  font-size: 20px; font-weight: 600; color: var(--fg);
  line-height: 1.35; letter-spacing: -0.011em;
  max-width: 38ch;
}

/* Options list — flat rows with breathing room between them. */
.ask-q-opts { display: flex; flex-direction: column; gap: 4px; }

.ask-opt {
  position: relative;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  width: 100%; text-align: start; cursor: pointer;
  padding: 11px 14px; border-radius: 8px;
  background: none; border: 0; color: var(--fg);
  font: inherit;
  transition: background-color 0.14s ease;
}
.ask-opt:hover { background: var(--surface); }
.ask-opt.is-focused { background: var(--surface); }
.ask-opt:focus-visible { outline: none; background: var(--surface); box-shadow: inset 0 0 0 1.5px var(--ember); }
.ask-opt.is-on { background: var(--ember-soft); }
.ask-opt:disabled { opacity: 0.55; cursor: not-allowed; }

.ask-opt-body { display: flex; flex-direction: column; gap: 3px; min-width: 0; flex: 1; }
.ask-opt-title { font-size: var(--text-sm); font-weight: 600; line-height: 1.45; color: var(--fg); }
.ask-opt-desc  { font-size: var(--text-base); color: var(--fg-muted); line-height: 1.5; }

/* Number badge — always visible, quiet by default. Brighter on hover/focus.
   Ember on selected (color + border + soft fill). */
.ask-opt-key {
  flex: 0 0 auto;
  display: inline-flex; align-items: center; justify-content: center;
  min-inline-size: 22px; block-size: 22px; padding-inline: 6px;
  font-family: var(--font-mono); font-size: 11px; line-height: 1;
  color: var(--fg-faint);
  border: 1px solid var(--border); border-radius: 4px;
  background: none;
  transition: color 0.14s ease, border-color 0.14s ease, background-color 0.14s ease;
}
.ask-opt:hover .ask-opt-key,
.ask-opt.is-focused .ask-opt-key {
  color: var(--fg-muted); border-color: var(--border-strong);
}
.ask-opt.is-on .ask-opt-key {
  color: var(--ember); border-color: var(--ember); background: var(--ember-soft);
}

/* Inline layout — description on the same line, "—" separator. */
.ask-q-opts.is-inline .ask-opt-body { flex-direction: row; flex-wrap: wrap; align-items: baseline; gap: 6px; }
.ask-q-opts.is-inline .ask-opt-sep { color: var(--fg-faint); }

/* "Other" — same row treatment, the input replaces title+desc. */
.ask-opt-other { padding: 11px 14px; cursor: text; }
.ask-opt-other input {
  background: none; border: 0; outline: none; width: 100%;
  color: var(--fg); font: inherit; font-size: var(--text-sm); line-height: 1.5;
}
.ask-opt-other input::placeholder { color: var(--fg-faint); }
.ask-opt-other.is-on input { color: var(--ember); }

/* Hint row — sits below the options, ABOVE the footer. Tiny supporting
   caption with keyboard tips, aligned to the leading edge. */
.ask-q-hint {
  display: flex; flex-wrap: wrap; gap: 12px;
  margin-top: 14px;
  font-size: 11px; color: var(--fg-faint); line-height: 1.5;
}
.ask-q-hint kbd {
  font-family: var(--font-mono); font-size: 10px; padding: 0 4px;
  border: 1px solid var(--border); border-radius: 3px;
  color: var(--fg-muted); background: none;
}

/* Footer — leading group (Back) on the start edge, trailing group
   (Skip + Continue) on the end edge. Empty leading container still
   participates in `justify-content: space-between` so the trailing
   group sits on the trailing edge even without Back. */
.ask-q-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-top: 14px; }
.ask-q-foot-leading,
.ask-q-foot-trailing { display: inline-flex; align-items: center; gap: 14px; }
.ask-q-foot-leading:empty { min-block-size: 0; }
.ask-q-back {
  display: inline-flex; align-items: center; gap: 5px;
  background: none; border: 0; padding: 0;
  color: var(--fg-muted); font: inherit; font-size: var(--text-sm); cursor: pointer;
  transition: color 0.14s ease;
}
.ask-q-back:hover { color: var(--fg); }
.ask-q-back:disabled { opacity: 0.4; cursor: not-allowed; }
.ask-q-cta {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 7px 14px; border-radius: 7px;
  background: var(--ember); border: 0; cursor: pointer;
  color: var(--ember-fg, #08090A); font: inherit; font-weight: 600;
  font-size: var(--text-sm);
  transition: opacity 0.14s ease, transform 0.06s ease;
}
.ask-q-cta:hover  { opacity: 0.92; }
.ask-q-cta:active { transform: translateY(0.5px); }
.ask-q-cta:disabled { background: var(--surface); color: var(--fg-faint); cursor: not-allowed; opacity: 1; }
.ask-q-cta.ghost {
  background: none; color: var(--fg-muted);
  box-shadow: inset 0 0 0 1px var(--border);
}
.ask-q-cta.ghost:hover { color: var(--ember); box-shadow: inset 0 0 0 1px var(--ember); opacity: 1; }

/* Completed summary — borderless dt/dd list, sans. */
.ask.is-done { background: none; padding: 0; }
.ask-done-head {
  display: inline-flex; align-items: center; gap: 6px;
  font-size: var(--text-sm); color: var(--ember); font-weight: 500;
  margin-bottom: 14px;
}
.ask-summary { display: grid; grid-template-columns: max-content 1fr; gap: 10px 24px; margin: 0; }
.ask-summary dt { font-size: var(--text-xs); color: var(--fg-faint); padding-top: 2px; line-height: 1.5; }
.ask-summary dd { margin: 0; font-size: var(--text-base); color: var(--fg); line-height: 1.5; }
.ask-summary dd.skipped { color: var(--fg-faint); font-style: italic; }
.ask-done-foot { margin-top: 22px; display: flex; gap: 8px; }

@media (prefers-reduced-motion: reduce) {
  .ask-q { animation: none; }
  .ask-q-progress-fill, .ask-opt, .ask-q-cta, .ask-opt-key { transition: none; }
}

@media (prefers-reduced-motion: reduce) {
  .ai-cot-body { transition: none; }
  .ai-cot .chev, .ask-opt, .ask-q-cta { transition: none; }
}

/* ModelSelector — keyboard focus highlight (matches :hover for arrow-key nav) */
.pi-menu-item.is-focused { background: var(--surface-active); outline: 1px solid var(--ember); outline-offset: -1px; }

/* Portaled ModelSelector menu — a SELF-CONTAINED class (it does NOT share
   `.pi-menu`'s in-flow positioning). React renders it under <body> via
   createPortal; only top/left/min-width are set inline. Everything else
   (sizing, visuals) lives right here. No !important needed because nothing
   else targets this class. */
.pi-menu-portal {
  position: fixed;
  z-index: 1200;
  max-height: 360px;
  overflow-y: auto;
  min-width: 220px;
  background: var(--bg-elevated);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 4px;
  box-shadow: 0 12px 32px rgba(0,0,0,0.42);
}
/* Reuse the same item styling as the in-flow menu — but scoped via
   descendant selector so we don't depend on the `.pi-menu` ancestor. */
.pi-menu-portal .pi-menu-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 10px; border-radius: 5px;
  font-size: var(--text-sm); color: var(--fg);
  cursor: pointer; white-space: nowrap;
}
.pi-menu-portal .pi-menu-item:hover { background: var(--surface-hover); }
.pi-menu-portal .pi-menu-item .sub { color: var(--fg-subtle); font-size: var(--text-xs); font-family: var(--font-mono); margin-inline-start: auto; }
.pi-menu-portal .pi-menu-item.is-active { background: var(--ember-soft); color: var(--ember); }
.pi-menu-portal .pi-menu-item.is-focused { background: var(--surface-active); outline: 1px solid var(--ember); outline-offset: -1px; }

/* "+" actions menu — portaled, sized for two-line items (label + description).
   Reuses .pi-menu-portal chrome (z-index, position:fixed, shadow), adds row
   layout for icon + text-stack. */
.pi-menu-portal.pi-actions-menu {
  min-width: 260px;
  padding: 6px;
}
.pi-actions-item {
  display: flex; align-items: flex-start; gap: 10px;
  inline-size: 100%;
  padding: 8px 10px;
  background: transparent; border: 0; border-radius: 6px;
  color: var(--fg); cursor: pointer; text-align: start;
  font: inherit;
  transition: background var(--dur-fast) var(--ease);
}
.pi-actions-item:hover,
.pi-actions-item:focus-visible {
  background: var(--surface-hover); outline: none;
}
.pi-actions-item.is-danger { color: var(--danger); }
.pi-actions-item.is-danger:hover { background: var(--danger-soft); }
.pi-actions-ico {
  display: inline-flex; align-items: center; justify-content: center;
  inline-size: 24px; block-size: 24px;
  border-radius: 6px;
  background: var(--surface-active);
  color: var(--fg-muted);
  flex: 0 0 auto;
  margin-top: 1px;
}
.pi-actions-item.is-danger .pi-actions-ico { background: var(--danger-soft); color: var(--danger); }
.pi-actions-text {
  display: flex; flex-direction: column; gap: 2px;
  min-inline-size: 0; flex: 1 1 auto;
}
.pi-actions-text .label {
  font-size: 13px; font-weight: 500; line-height: 1.3;
  color: inherit;
}
.pi-actions-text .desc {
  font-size: var(--text-xs); color: var(--fg-faint); line-height: 1.4;
}
.pi-actions-divider {
  block-size: 1px;
  background: var(--border);
  margin: 4px 6px;
}

/* ── ContextGauge / ContextBar — LLM context-window indicator ── */
.ai-ctx-gauge {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--fg-muted); font-family: var(--font-mono); font-size: var(--text-xs);
  line-height: 1; user-select: none;
}
.ai-ctx-gauge svg { display: block; flex: 0 0 auto; }
.ai-ctx-gauge.tone-mid  { color: var(--warning, #FBBF24); }
.ai-ctx-gauge.tone-warn { color: var(--danger,  #FF453A); }
.ai-ctx-gauge-label { display: inline-flex; gap: 3px; align-items: baseline; }
.ai-ctx-gauge-label .used { color: var(--fg); }
.ai-ctx-gauge-label .of { color: var(--fg-faint); }
.ai-ctx-gauge-label .total { color: var(--fg-muted); }
.ai-ctx-gauge-label .pct { color: currentColor; }
.ai-ctx-gauge-label .files { color: var(--fg-faint); margin-inline-start: 4px; }
.ai-ctx-gauge.tone-mid  .ai-ctx-gauge-label .used,
.ai-ctx-gauge.tone-warn .ai-ctx-gauge-label .used { color: currentColor; }

.ai-ctx-bar {
  display: inline-flex; align-items: center; gap: 8px;
  color: var(--fg-muted); font-family: var(--font-mono); font-size: var(--text-xs);
  line-height: 1;
}
.ai-ctx-bar.tone-mid  { color: var(--warning, #FBBF24); }
.ai-ctx-bar.tone-warn { color: var(--danger,  #FF453A); }
.ai-ctx-bar-track {
  flex: 0 0 auto; inline-size: 90px; block-size: 4px;
  background: var(--surface-active, var(--surface));
  border-radius: 999px; overflow: hidden;
}
.ai-ctx-bar-fill {
  display: block; block-size: 100%;
  background: currentColor; border-radius: 999px;
  transition: inline-size 0.24s ease;
}
.ai-ctx-bar-label { display: inline-flex; gap: 3px; align-items: baseline; }
.ai-ctx-bar-label .used { color: var(--fg); }
.ai-ctx-bar-label .of { color: var(--fg-faint); }
.ai-ctx-bar-label .total { color: var(--fg-muted); }
.ai-ctx-bar-label .files { color: var(--fg-faint); margin-inline-start: 4px; }
.ai-ctx-bar.tone-mid  .ai-ctx-bar-label .used,
.ai-ctx-bar.tone-warn .ai-ctx-bar-label .used { color: currentColor; }

.pi-foot .pi-ctx-slot { display: inline-flex; align-items: center; margin-inline-end: 6px; }

/* ════════════════════════════════════════════════════════════════════════
   Artifact — widget (in-chat chip) + side panel (docked host)
   (core/ai/artifact.tsx)
   ════════════════════════════════════════════════════════════════════════ */

/* WIDGET — compact card in a Message bubble. Flat: hairline border, ember
   on hover. Click → open the panel. */
.ai-art-widget {
  display: inline-flex; align-items: center; gap: 12px;
  width: 100%; max-width: 360px; min-width: 0;
  padding: 10px 12px; border-radius: 10px;
  background: var(--surface); border: 1px solid var(--border);
  color: var(--fg); text-align: start; cursor: pointer;
  transition: border-color 0.14s ease, background 0.14s ease;
}
.ai-art-widget:hover { border-color: var(--ember); background: var(--ember-soft); }
.ai-art-widget:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }
.ai-art-widget-ico {
  flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center;
  width: 30px; height: 30px; border-radius: 7px;
  background: var(--ember-soft); color: var(--ember);
}
.ai-art-widget-text { display: flex; flex-direction: column; gap: 2px; min-width: 0; flex: 1; }
.ai-art-widget-title {
  font-size: var(--text-sm); font-weight: 600; color: var(--fg);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.ai-art-widget-meta {
  font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint);
  text-transform: uppercase; letter-spacing: 0.06em;
}
.ai-art-widget-action {
  flex: 0 0 auto; color: var(--fg-faint);
  transition: color 0.14s ease;
}
.ai-art-widget:hover .ai-art-widget-action { color: var(--ember); }

/* PANEL — the artifact wraps the core <Drawer/> in inline mode. The
   Drawer provides the outer chrome (.dr-header/.dr-body) and the docked
   sliding behavior; these rules style the artifact-specific bits inside
   that chrome (the title row and the tabs strip).
   ─────────────────────────────────────────────────────────────────────── */

/* Title row that lives in .dr-header's title slot — icon + title stack +
   actions, with the Drawer's built-in close button to its trailing edge. */
.ai-art-panel-title-row {
  display: flex; align-items: center; gap: 10px;
  min-inline-size: 0; flex: 1;
}
.ai-art-panel-ico {
  flex: 0 0 auto; display: inline-flex; align-items: center; justify-content: center;
  inline-size: 28px; block-size: 28px; border-radius: 6px;
  background: var(--ember-soft); color: var(--ember);
}
.ai-art-panel-text { display: flex; flex-direction: column; gap: 1px; min-inline-size: 0; flex: 1; }
.ai-art-panel-title { font-size: var(--text-sm); font-weight: 600; color: var(--fg); }
.ai-art-panel-meta {
  font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint);
  text-transform: uppercase; letter-spacing: 0.06em;
}
.ai-art-panel-actions { display: inline-flex; align-items: center; gap: 4px; margin-inline-start: auto; }

/* Tabs — sit at the top of the drawer body. Negative top margin so they
   align flush with the .dr-body padding edge. */
.ai-art-panel-tabs {
  display: flex; gap: 2px;
  margin: -22px -28px 16px;  /* cancel .dr-body padding for a full-bleed strip */
  padding: 0 28px;
  border-bottom: 1px solid var(--border);
}
.ai-art-panel-tab {
  background: none; border: 0; padding: 10px 0;
  margin-inline-end: 16px;
  color: var(--fg-muted); font: inherit; font-size: var(--text-sm);
  cursor: pointer; position: relative;
}
.ai-art-panel-tab:hover { color: var(--fg); }
.ai-art-panel-tab.is-active { color: var(--ember); }
.ai-art-panel-tab.is-active::after {
  content: ''; position: absolute; inset-inline: 0; bottom: -1px;
  block-size: 2px; background: var(--ember);
}
.ai-art-panel-body { /* no extra padding — .dr-body already provides it */ }

/* Default content renderers */
.ai-art-doc p { margin: 0 0 12px; line-height: 1.6; color: var(--fg); }
.ai-art-doc p:last-child { margin-bottom: 0; }
.ai-art-html { color: var(--fg); }
.ai-art-app-fallback {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 10px; padding: 32px 16px; color: var(--fg-muted); text-align: center;
}
.ai-art-app-fallback svg { color: var(--ember); }
.ai-art-app-fallback p { font-size: var(--text-base); max-width: 36ch; line-height: 1.5; }
.ai-art-app-fallback code { font-family: var(--font-mono); font-size: var(--text-xs); color: var(--ember); }
.ai-art-code {
  margin: 0; padding: 12px; background: var(--bg);
  border: 1px solid var(--border); border-radius: 8px;
  overflow-x: auto;
  font-family: var(--font-mono); font-size: var(--text-base);
  color: var(--fg); line-height: 1.55;
}
.ai-art-empty {
  color: var(--fg-faint); font-style: italic;
  font-size: var(--text-base);
}

/* ════════════════════════════════════════════════════════════════════════
   Terminal — paired commands + output surface (core/ai/terminal.tsx)
   ════════════════════════════════════════════════════════════════════════ */
.ai-term {
  background: var(--bg); border: 1px solid var(--border);
  border-radius: 10px; overflow: hidden;
  max-width: 720px;
}
.ai-term-head {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 12px;
  background: var(--bg-elevated); border-bottom: 1px solid var(--border);
}
.ai-term-ico {
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ember);
}
.ai-term-title {
  font-family: var(--font-mono); font-size: var(--text-xs);
  color: var(--fg-muted); flex: 1;
}
.ai-term-status {
  font-family: var(--font-mono); font-size: 10px;
  text-transform: uppercase; letter-spacing: 0.08em;
  padding: 2px 8px; border-radius: 4px;
  background: var(--surface); color: var(--fg-muted);
}
.ai-term-status.running { color: var(--ember); background: var(--ember-soft); }
.ai-term-status.done    { color: var(--success, #34c759); background: rgba(52,199,89,0.12); }
.ai-term-status.error   { color: var(--danger,  #ff453a); background: rgba(255,69,58,0.12); }
.ai-term-body {
  padding: 12px 14px;
  font-family: var(--font-mono); font-size: var(--text-base);
  line-height: 1.6; color: var(--fg);
  overflow-x: auto;
}
.ai-term-line { display: flex; align-items: flex-start; gap: 8px; white-space: pre-wrap; }
.ai-term-line + .ai-term-line { margin-top: 2px; }
.ai-term-line.in { color: var(--fg); }
.ai-term-line.in .ai-term-prompt { color: var(--ember); flex: 0 0 auto; user-select: none; }
.ai-term-line.out { color: var(--fg-muted); }
.ai-term-line.err { color: var(--danger, #ff453a); }
.ai-term-line.err .ai-term-mark { color: var(--danger); display: inline-flex; padding-top: 4px; }
.ai-term-line.note {
  color: var(--fg-faint); font-style: italic;
  margin-block: 6px; padding-inline-start: 12px;
  border-inline-start: 2px solid var(--border);
}
.ai-term-text { flex: 1; min-width: 0; }

/* ════════════════════════════════════════════════════════════════════════
   Voice — Persona / SpeechInput / Transcription / AudioPlayer
   (core/ai/voice.tsx)
   ════════════════════════════════════════════════════════════════════════ */

/* Persona — orb with state animations. Ember radial gradient inner; outer
   ring shifts by state. */
.ai-persona { display: inline-block; position: relative; }
.ai-persona svg { display: block; }
.ai-persona-ring {
  fill: none; stroke: var(--border); stroke-width: 1.5;
}
.ai-persona-orb { transition: transform 0.4s var(--ease, ease); transform-origin: 50% 50%; }

/* idle — quiet, no animation */
.ai-persona.is-idle .ai-persona-ring { stroke: var(--border); }

/* listening — outer ring pulses ember */
.ai-persona.is-listening .ai-persona-ring {
  stroke: var(--ember); stroke-width: 2;
  animation: ai-persona-pulse 1.6s ease-in-out infinite;
}
@keyframes ai-persona-pulse {
  0%, 100% { stroke-opacity: 1; }
  50%      { stroke-opacity: 0.35; }
}

/* thinking — dashed rotating ring */
.ai-persona.is-thinking .ai-persona-ring {
  stroke: var(--ember); stroke-width: 1.5;
  stroke-dasharray: 12 8; transform-origin: 50% 50%;
  animation: ai-persona-rotate 2.4s linear infinite;
}
@keyframes ai-persona-rotate {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}

/* speaking — orb expands/contracts like a soft breath */
.ai-persona.is-speaking .ai-persona-orb {
  animation: ai-persona-breathe 1.2s ease-in-out infinite;
}
.ai-persona.is-speaking .ai-persona-ring {
  stroke: var(--ember); stroke-width: 2;
}
@keyframes ai-persona-breathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.06); }
}

/* SpeechInput — compact (icon-only, slots into PromptInput footer next to
   the paperclip). Inherits .pi-tool base; state class adds ember pulse /
   danger / processing tints. */
.ai-speech-tool.is-listening {
  color: var(--ember-fg, #08090A);
  background: var(--ember);
  border-color: var(--ember);
  animation: ai-persona-pulse 1.6s ease-in-out infinite;
}
.ai-speech-tool.is-listening:hover { background: var(--ember); color: var(--ember-fg, #08090A); }
.ai-speech-tool.is-processing { color: var(--ember); background: var(--ember-soft); }
.ai-speech-tool.is-error { color: var(--danger, #FF453A); }
.ai-speech-tool.is-error:hover { color: var(--danger, #FF453A); background: rgba(255,69,58,0.10); }

/* SpeechInput — full surface (dedicated voice screen). */
.ai-speech {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 12px;
  border: 1px solid var(--border); border-radius: 12px;
  background: var(--surface); max-width: 480px;
}
.ai-speech.is-listening { border-color: var(--ember); background: var(--ember-soft); }
.ai-speech.is-error     { border-color: var(--danger, #FF453A); }
.ai-speech-mic {
  flex: 0 0 auto;
  display: inline-flex; align-items: center; justify-content: center;
  width: 36px; height: 36px; border-radius: 999px;
  background: var(--ember); color: var(--ember-fg, #08090A);
  border: 0; cursor: pointer;
  transition: transform 0.12s ease;
}
.ai-speech-mic:hover { transform: scale(1.04); }
.ai-speech-mic:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }
.ai-speech-tool:focus-visible { outline: 2px solid var(--ember); outline-offset: 2px; }
.ai-speech.is-idle .ai-speech-mic { background: var(--surface-active); color: var(--fg); }
.ai-speech.is-listening .ai-speech-mic {
  animation: ai-persona-pulse 1.6s ease-in-out infinite;
}
.ai-speech.is-processing .ai-speech-mic { background: var(--surface-active); color: var(--ember); }
.ai-speech.is-error .ai-speech-mic { background: var(--danger, #FF453A); color: #fff; }
.ai-speech-body { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.ai-speech-hint { color: var(--fg-muted); font-size: var(--text-sm); }
.ai-speech-transcript { color: var(--fg); font-size: var(--text-sm); line-height: 1.45; }
.ai-speech-wave {
  display: inline-flex; align-items: center; gap: 2px; height: 22px;
}
.ai-speech-bar {
  display: inline-block; width: 3px; height: 100%; border-radius: 2px;
  background: var(--ember); transform-origin: 50% 50%;
  transition: transform 0.08s linear;
}

/* Transcription */
.ai-transcript { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 14px; }
.ai-transcript-turn { display: flex; gap: 10px; }
.ai-transcript-chip {
  flex: 0 0 auto;
  display: inline-flex; align-items: center; justify-content: center;
  width: 24px; height: 24px; border-radius: 50%;
  background: var(--surface-active); border: 1px solid var(--border);
  color: var(--fg-muted);
  font: 600 11px/1 var(--font-mono);
  text-transform: uppercase;
}
.ai-transcript-turn.is-user .ai-transcript-chip {
  background: var(--ember-soft); border-color: rgba(255,107,53,0.25);
  color: var(--ember);
}
.ai-transcript-text { display: flex; flex-direction: column; gap: 4px; flex: 1; min-width: 0; }
.ai-transcript-meta {
  display: inline-flex; align-items: baseline; gap: 8px;
  font-family: var(--font-mono); font-size: var(--text-xs); color: var(--fg-faint);
}
.ai-transcript-speaker { color: var(--fg); font-weight: 500; }
.ai-transcript-time { color: var(--fg-faint); }
.ai-transcript-conf {
  background: var(--surface); border: 1px solid var(--border);
  padding: 0 5px; border-radius: 3px; color: var(--fg-muted);
}
/* Confidence tiers — high (default) stays muted; mid uses amber, low red.
   Text colour alone satisfies the contract; borders tinted for a stronger
   signal. Theme-aware --warning / --danger only, no hardcoded hex. */
.ai-transcript-conf.is-mid {
  color: var(--warning);
  border-color: color-mix(in srgb, var(--warning) 45%, var(--border));
}
.ai-transcript-conf.is-low {
  color: var(--danger);
  border-color: color-mix(in srgb, var(--danger) 45%, var(--border));
}
.ai-transcript-line { margin: 0; font-size: var(--text-base); line-height: 1.55; color: var(--fg); }

/* AudioPlayer — richer flat layout: cover · controls · body (meta + scrubber)
   · speed · mute. Switches the scrubber to a real waveform when `peaks`
   is passed. */
.ai-audio {
  display: flex; align-items: center; gap: 12px;
  padding: 10px 14px; max-width: 560px;
  background: var(--surface); border: 1px solid var(--border); border-radius: 14px;
}
.ai-audio.has-cover { gap: 14px; }

.ai-audio-cover {
  flex: 0 0 auto;
  inline-size: 48px; block-size: 48px;
  border-radius: 8px; overflow: hidden;
  background: var(--surface-active);
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ember);
}
.ai-audio-cover img { inline-size: 100%; block-size: 100%; object-fit: cover; display: block; }

.ai-audio-controls {
  flex: 0 0 auto;
  display: inline-flex; align-items: center; gap: 4px;
}
.ai-audio-btn {
  flex: 0 0 auto;
  display: inline-flex; align-items: center; justify-content: center;
  background: none; border: 0; cursor: pointer;
  color: var(--fg-muted);
  transition: color 0.14s ease, background 0.14s ease;
}
.ai-audio-btn.skip {
  inline-size: 28px; block-size: 28px; border-radius: 6px;
}
.ai-audio-btn.skip:hover { color: var(--ember); background: var(--ember-soft); }
.ai-audio-btn.play {
  inline-size: 36px; block-size: 36px; border-radius: 50%;
  background: var(--ember); color: var(--ember-fg, #08090A);
}
.ai-audio-btn.play:hover { opacity: 0.92; }
.ai-audio-btn.mute {
  inline-size: 28px; block-size: 28px; border-radius: 6px;
}
.ai-audio-btn.mute:hover { color: var(--ember); background: var(--ember-soft); }

.ai-audio-body { flex: 1; min-inline-size: 0; display: flex; flex-direction: column; gap: 6px; }
.ai-audio-meta {
  display: flex; align-items: baseline; gap: 8px;
  font-size: var(--text-xs); color: var(--fg-muted);
}
.ai-audio-title { color: var(--fg); font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ai-audio-subtitle { color: var(--fg-faint); }
.ai-audio-row { display: flex; align-items: center; gap: 10px; }
.ai-audio-time {
  font-family: var(--font-mono); font-size: var(--text-xs);
  color: var(--fg-faint); tab-size: 2; min-inline-size: 34px;
}

/* Track — plain bar (default) or waveform (when peaks are passed). */
.ai-audio-track {
  flex: 1; position: relative; block-size: 22px;
  display: flex; align-items: center;
  cursor: pointer; outline: none;
}
.ai-audio-track:focus-visible { box-shadow: 0 0 0 2px var(--ember); border-radius: 4px; }
.ai-audio-track-bar {
  position: relative; display: block;
  inline-size: 100%; block-size: 4px;
  background: var(--surface-active); border-radius: 999px; overflow: hidden;
}
.ai-audio-track-bar::after {
  content: ''; position: absolute; inset-inline-start: 0; inset-block: 0;
  inline-size: var(--pct, 0%); background: var(--ember); border-radius: 999px;
}

/* Waveform variant */
.ai-audio-wave {
  inline-size: 100%; block-size: 100%;
  display: flex; align-items: center; gap: 2px;
}
.ai-audio-wave-bar {
  flex: 1; display: inline-block;
  inline-size: 2px; min-inline-size: 2px;
  background: var(--surface-active);
  border-radius: 1px;
  transition: background 0.12s ease;
}
.ai-audio-wave-bar.is-played { background: var(--ember); }

/* Speed selector — pill that cycles on click. */
.ai-audio-speed {
  flex: 0 0 auto;
  font-family: var(--font-mono); font-size: var(--text-xs); font-weight: 500;
  padding: 3px 8px; border-radius: 5px;
  background: none; border: 1px solid var(--border);
  color: var(--fg-muted); cursor: pointer;
  transition: color 0.14s ease, border-color 0.14s ease, background 0.14s ease;
  min-inline-size: 36px;
}
.ai-audio-speed:hover { color: var(--ember); border-color: var(--ember); background: var(--ember-soft); }

@media (prefers-reduced-motion: reduce) {
  .ai-persona-ring, .ai-persona-orb, .ai-speech-mic, .ai-speech-bar { animation: none; transition: none; }
  .ai-audio-btn, .ai-audio-wave-bar, .ai-audio-speed { transition: none; }
}

/* ════════════════════════════════════════════════════════════════════════
   Drawer (core/drawer.tsx) — overlay (portaled, fixed) OR inline (docked
   into a flex/grid layout so siblings actually shrink to make room).
   Lives here in ai.css rather than ds.css so the existing ds.css doesn't
   grow further; ai.css already loads on every route.
   ════════════════════════════════════════════════════════════════════════ */

/* ── OVERLAY variant — portaled, fixed, with backdrop ── */
.dr-root.variant-overlay .dr-overlay {
  position: fixed; inset: 0; z-index: 60;
  background: rgba(0,0,0,0.45);
  opacity: 0;
  transition: opacity 240ms cubic-bezier(0.32, 0.72, 0, 1);
  pointer-events: none;
}
[data-theme="light"] .dr-root.variant-overlay .dr-overlay { background: rgba(0,0,0,0.30); }
.dr-root.variant-overlay[data-state="open"] .dr-overlay { opacity: 1; pointer-events: auto; }

.dr-root.variant-overlay .dr {
  position: fixed; z-index: 61;
  background: var(--bg-elevated);
  display: flex; flex-direction: column;
  box-shadow: 0 18px 60px rgba(0,0,0,0.45);
  transition: transform 280ms cubic-bezier(0.32, 0.72, 0, 1);
  will-change: transform;
}
[data-theme="light"] .dr-root.variant-overlay .dr { box-shadow: 0 18px 60px rgba(0,0,0,0.18); }

.dr-root.variant-overlay .dr.right  { top: 0; bottom: 0; inset-inline-end: 0;
  inline-size: var(--dr-w, 460px); max-inline-size: 100%;
  border-inline-start: 1px solid var(--border);
  transform: translate3d(100%, 0, 0); }
.dr-root.variant-overlay .dr.left   { top: 0; bottom: 0; inset-inline-start: 0;
  inline-size: var(--dr-w, 360px); max-inline-size: 100%;
  border-inline-end: 1px solid var(--border);
  transform: translate3d(-100%, 0, 0); }
.dr-root.variant-overlay .dr.top    { top: 0; left: 0; right: 0;
  block-size: var(--dr-h, 320px); border-bottom: 1px solid var(--border);
  transform: translate3d(0, -100%, 0); }
.dr-root.variant-overlay .dr.bottom { bottom: 0; left: 0; right: 0;
  block-size: var(--dr-h, 360px); border-top: 1px solid var(--border);
  border-radius: 16px 16px 0 0;
  transform: translate3d(0, 100%, 0); }

[dir="rtl"] .dr-root.variant-overlay .dr.right { transform: translate3d(-100%, 0, 0); }
[dir="rtl"] .dr-root.variant-overlay .dr.left  { transform: translate3d(100%, 0, 0); }

.dr-root.variant-overlay[data-state="open"] .dr { transform: translate3d(0, 0, 0) !important; }

/* ── INLINE variant — docks into the parent layout. Siblings shrink. ── */
/* The root is the layout participant — `inline-size` animates. */
.dr-root.variant-inline {
  display: flex;
  block-size: 100%;
  inline-size: 0;
  overflow: hidden;
  transition: inline-size 280ms cubic-bezier(0.32, 0.72, 0, 1);
  flex: 0 0 auto;
}
.dr-root.variant-inline[data-state="open"] { inline-size: var(--dr-w, 460px); }
.dr-root.variant-inline .dr {
  display: flex; flex-direction: column;
  inline-size: var(--dr-w, 460px);
  block-size: 100%;
  background: var(--bg-elevated);
  border-inline-start: 1px solid var(--border);
}
.dr-root.variant-inline .dr.left { border-inline-start: 0; border-inline-end: 1px solid var(--border); }
.dr-root.variant-inline .dr.top,
.dr-root.variant-inline .dr.bottom {
  /* In inline mode, top/bottom equal left/right semantically — the parent
     decides direction. We keep block-size 100% for simplicity. */
  inline-size: 100%; block-size: var(--dr-h, 320px);
}

/* ── Drag handle (bottom drawer overlay only) ── */
.dr-drag { cursor: grab; touch-action: none; -webkit-user-select: none; user-select: none; }
.dr-drag:active { cursor: grabbing; }
.dr-drag .dr-grip .bar {
  transition: background var(--dur-fast) var(--ease), width var(--dur-fast) var(--ease);
}
.dr-drag:hover .dr-grip .bar { background: var(--fg-faint); width: 48px; }
.dr-grip { display: flex; justify-content: center; padding: 10px 0 4px; }
.dr-grip .bar { width: 40px; height: 4px; border-radius: 2px; background: var(--border-strong); }

/* ── Header / body / footer ── */
.dr-header {
  display: flex; align-items: flex-start; gap: 14px;
  padding: 22px 28px 16px;
  border-bottom: 1px solid var(--border);
  flex: 0 0 auto;
}
.dr-title { flex: 1; font: 600 16px/1.3 var(--font, var(--body)); color: var(--fg); letter-spacing: -0.01em; }
.dr-desc { font: 400 13px/1.55 var(--font, var(--body)); color: var(--fg-muted); margin-top: 4px; }
.dr-close {
  flex: 0 0 auto;
  width: 32px; height: 32px; border-radius: 6px;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--fg-faint); background: transparent; border: none; cursor: pointer;
  transition: background var(--dur-fast) var(--ease), color var(--dur-fast) var(--ease);
}
.dr-close:hover { background: var(--surface-hover); color: var(--fg); }

.dr-body {
  flex: 1; min-block-size: 0; overflow-y: auto;
  padding: 22px 28px;
}
.dr-footer {
  padding: 16px 28px;
  border-top: 1px solid var(--border);
  display: flex; gap: 10px; justify-content: flex-end;
  flex: 0 0 auto;
}

@media (max-width: 540px) {
  .dr-header, .dr-footer { padding-inline: 20px; }
  .dr-body { padding-inline: 20px; }
}
